"""Source and statement resolution between parsing and binding.

This stage owns everything that maps a parsed statement onto the actual
sources without ever reading table data: ``sources`` argument validation,
join-strategy validation (shared with the join layer), table-name
resolution, the qualified-name rewrite that canonicalises every column
reference, the joined-schema derivation shared by execution and explain,
and the metadata-to-schema helpers.  Unreferenced sources are never
opened; the only bytes read here are the 5-byte format-version prefix
peek, which treats anything unreadable as v1 so the historical read order
and error behaviour are preserved.
"""

from __future__ import annotations

import os
from collections.abc import Mapping
from dataclasses import dataclass
from typing import Any

from .errors import QuerySyntaxError, QueryValidationError
from .format import ColumnSchema, Schema, Table
from .join import _derive_step_schema, _validate_join_strategy
from .parser import _Parser, _RefItem, _Select, _tokenize


def _peek_format_version(path: Any) -> int | None:
    """Best-effort read of a file's format version byte (no validation).

    Returns ``None`` for unreadable or unrecognisable files; callers treat
    that as "not v2" so the legacy read path reports the proper error.
    """
    try:
        with open(path, "rb") as handle:
            prefix = handle.read(5)
    except OSError:
        return None
    if len(prefix) < 5 or prefix[:4] != b"CAEF":
        return None
    return prefix[4]
def _qualify_table(table: Table, key: str) -> Table:
    """Re-wrap ``table`` naming every column ``key.column`` (values unchanged)."""
    qualified = Schema(
        tuple(
            ColumnSchema(f"{key}.{col.name}", col.type, col.nullable)
            for col in table.schema.columns
        )
    )
    return Table._from_storage(qualified, table._columns)


def _validate_sources(sources: Any) -> dict:
    if not isinstance(sources, Mapping):
        raise ValueError("sources must be a mapping of table names to file paths")
    if not sources:
        raise ValueError("sources must not be empty")
    paths = {}
    for key, value in sources.items():
        if not isinstance(key, str) or not key:
            raise ValueError("sources keys must be non-empty strings")
        if not isinstance(value, (str, os.PathLike)):
            raise ValueError(f"sources[{key!r}] must be a file path")
        paths[key] = value
    return paths


@dataclass(frozen=True)
class _JoinStep:
    """One validated join step, normalised to intermediate-vs-new sides."""

    kind: str  # "inner" | "left" | "right" | "full"
    prior_key: str  # canonical table of the ON side already introduced
    prior_col: str
    new_key: str  # canonical table freshly introduced by this step
    new_col: str


def _resolve_statement(sources: Any, sql: str, join_strategy: Any = None) -> tuple:
    """Validate arguments and resolve the statement's table/ON references.

    No file is ever opened: only argument validation, parsing and name
    resolution run here.  Returns ``(paths, select, strategy, from_key,
    steps)`` with ``steps`` a tuple of :class:`_JoinStep` in FROM/JOIN
    order (empty for a single-table statement).
    """
    strategy = _validate_join_strategy(join_strategy)
    paths = _validate_sources(sources)
    tokens = _tokenize(sql)
    select = _Parser(tokens, allow_join=True).parse()
    all_keys = tuple(paths)
    from_key = _resolve_table_ref(select.table, select.table_quoted, all_keys)
    introduced = [from_key]
    steps: list[_JoinStep] = []
    for join in select.joins:
        new_key = _resolve_table_ref(join.table, join.table_quoted, all_keys)
        if new_key in introduced:
            raise QueryValidationError(f"duplicate table {new_key!r} in join")
        candidates = (*introduced, new_key)
        left_table = _resolve_table_ref(
            join.left_key[0], join.left_key[1], candidates
        )
        right_table = _resolve_table_ref(
            join.right_key[0], join.right_key[1], candidates
        )
        left_is_new = left_table == new_key
        right_is_new = right_table == new_key
        # Exactly one ON side introduces this step's new table; the other
        # must name a table introduced by FROM or an earlier join.
        if left_is_new == right_is_new:
            raise QueryValidationError(
                "ON keys must connect the newly joined table with an earlier table"
            )
        if left_is_new:
            prior_key, prior_col = right_table, join.right_key[2]
            new_col = join.left_key[2]
        else:
            prior_key, prior_col = left_table, join.left_key[2]
            new_col = join.right_key[2]
        steps.append(
            _JoinStep(join.kind, prior_key, prior_col, new_key, new_col)
        )
        introduced.append(new_key)
    return paths, select, strategy, from_key, tuple(steps)


def _referenced_source_paths(sources: Any, sql: str, join_strategy: Any = None) -> tuple:
    """Resolve the file paths of the tables the statement actually reads.

    Parsing-only counterpart of :func:`query_files`: no file is ever opened.
    Returns the paths in ``FROM`` / ``JOIN`` order (one entry for a
    single-table statement, one per introduced table otherwise).  Source and
    join-strategy validation raise :class:`ValueError`; lexical / grammatical
    errors raise :class:`QuerySyntaxError`; unknown or ambiguous table names
    and other join-shape problems raise :class:`QueryValidationError`.
    """
    paths, _select, _strategy, from_key, steps = _resolve_statement(
        sources, sql, join_strategy
    )
    return (paths[from_key], *(paths[step.new_key] for step in steps))


def _resolve_table_ref(name: str, quoted: bool, candidates: tuple) -> str:
    """Resolve a table reference against the available canonical names.

    Quoted references match exactly; bare references match exactly first,
    then case-insensitively when that is unambiguous.
    """
    if name in candidates:
        return name
    if not quoted:
        lowered = name.lower()
        matches = [c for c in candidates if c.lower() == lowered]
        if len(matches) == 1:
            return matches[0]
        if len(matches) > 1:
            raise QueryValidationError(f"ambiguous table name {name!r}")
    raise QueryValidationError(f"unknown table {name!r}")


def _single_table_resolver(table_key: str):
    def resolve(table, table_quoted, column):
        if table is not None:
            _resolve_table_ref(table, table_quoted, (table_key,))
        return column

    return resolve


def _multi_table_resolver(table_keys: tuple):
    def resolve(table, table_quoted, column):
        if table is None:
            raise QueryValidationError(
                f"column reference {column!r} must be qualified with a table name"
            )
        key = _resolve_table_ref(table, table_quoted, table_keys)
        return f"{key}.{column}"

    return resolve


def _rewrite_select(select: _Select, resolve) -> _Select:
    """Resolve every column reference to its canonical output name."""
    items = tuple(_rewrite_ref_item(item, resolve) for item in select.items)
    # ORDER BY names that match a SELECT alias stay unresolved here; the
    # binder resolves them against the aliased expressions first.
    aliases = {item.name for item in items if item.kind == "expr"}
    group_by = None
    if select.group_by is not None:
        group_by = tuple(
            (None, False, resolve(table, quoted, name))
            for table, quoted, name in select.group_by
        )
    order_by = None
    if select.order_by is not None:
        order_by = tuple(
            item
            if item.kind == "column" and item.table is None and item.name in aliases
            else _rewrite_ref_item(item, resolve)
            for item in select.order_by
        )
    where = _rewrite_expr(select.where, resolve) if select.where is not None else None
    having = (
        _rewrite_having_expr(select.having, resolve)
        if select.having is not None
        else None
    )
    return _Select(
        items=items,
        table=select.table,
        table_quoted=select.table_quoted,
        where=where,
        group_by=group_by,
        having=having,
        order_by=order_by,
        limit=select.limit,
        joins=select.joins,
        distinct=select.distinct,
    )


def _rewrite_ref_item(item: _RefItem, resolve) -> _RefItem:
    if item.kind == "star":
        return item
    if item.kind == "expr":
        return _RefItem(
            "expr",
            name=item.name,
            expr=_rewrite_expr(item.expr, resolve),
            descending=item.descending,
            nulls_first=item.nulls_first,
        )
    if item.kind == "column":
        return _RefItem(
            "column",
            name=resolve(item.table, item.table_quoted, item.name),
            descending=item.descending,
            nulls_first=item.nulls_first,
        )
    arg = item.arg
    if arg:
        arg = resolve(item.arg_table, item.arg_table_quoted, arg)
    return _RefItem(
        "agg",
        func=item.func,
        arg=arg,
        distinct=item.distinct,
        descending=item.descending,
        nulls_first=item.nulls_first,
    )


def _rewrite_expr(node: tuple, resolve) -> tuple:
    tag = node[0]
    if tag == "literal":
        return node
    if tag == "column":
        return ("column", resolve(node[2], node[3], node[1]), None, False)
    if tag == "unary":
        return ("unary", _rewrite_expr(node[1], resolve), node[2])
    if tag == "arith":
        return ("arith", node[1], _rewrite_expr(node[2], resolve), _rewrite_expr(node[3], resolve))
    if tag == "case":
        return (
            "case",
            tuple(
                (_rewrite_expr(cond, resolve), _rewrite_expr(result, resolve))
                for cond, result in node[1]
            ),
            _rewrite_expr(node[2], resolve) if node[2] is not None else None,
        )
    if tag == "not":
        return ("not", _rewrite_expr(node[1], resolve))
    if tag in ("and", "or"):
        return (tag, _rewrite_expr(node[1], resolve), _rewrite_expr(node[2], resolve))
    if tag == "isnull":
        return ("isnull", _rewrite_expr(node[1], resolve), node[2])
    if tag == "cmp":
        return ("cmp", node[1], _rewrite_expr(node[2], resolve), _rewrite_expr(node[3], resolve))
    if tag == "in":
        # Options are parser-restricted to literal constants, so the
        # operand is the only subtree carrying column references.
        return ("in", _rewrite_expr(node[1], resolve), node[2], node[3])
    raise QuerySyntaxError(f"unsupported expression: {tag}")  # pragma: no cover - defensive


def _rewrite_having_expr(node: tuple, resolve) -> tuple:
    """Rewrite column and aggregate references inside a parsed HAVING tree."""
    tag = node[0]
    if tag == "literal":
        return node
    if tag == "column":
        return ("column", resolve(node[2], node[3], node[1]), None, False)
    if tag == "hagg":
        arg = node[2]
        if arg:
            arg = resolve(node[3], node[4], arg)
        return ("hagg", node[1], arg, None, False, node[5])
    if tag == "not":
        return ("not", _rewrite_having_expr(node[1], resolve))
    if tag in ("and", "or"):
        return (
            tag,
            _rewrite_having_expr(node[1], resolve),
            _rewrite_having_expr(node[2], resolve),
        )
    if tag == "isnull":
        return ("isnull", _rewrite_having_expr(node[1], resolve), node[2])
    if tag == "cmp":
        return (
            "cmp",
            node[1],
            _rewrite_having_expr(node[2], resolve),
            _rewrite_having_expr(node[3], resolve),
        )
    if tag == "in":
        # Options are constant literals; only the operand may carry a
        # group column or an aggregate reference.
        return ("in", _rewrite_having_expr(node[1], resolve), node[2], node[3])
    raise QuerySyntaxError(f"unsupported expression: {tag}")  # pragma: no cover - defensive


def _build_joined_schema(
    prior_schema: Schema,
    new_schema: Schema,
    step: _JoinStep,
) -> Schema:
    """Validate one step's ON keys and derive the combined post-step schema.

    Name resolution, key-type compatibility and duplicate result names are
    query-layer concerns and stay here (keeping their
    :class:`QueryValidationError` classification); the resulting column
    layout and outer-join nullability are derived by the shared join layer
    so execution and the explain plan can never disagree.
    """
    prior_name = f"{step.prior_key}.{step.prior_col}"
    try:
        prior_idx = prior_schema.index(prior_name)
    except KeyError:
        raise QueryValidationError(f"unknown column: {prior_name!r}") from None
    try:
        new_idx = new_schema.index(step.new_col)
    except KeyError:
        raise QueryValidationError(
            f"unknown column: {f'{step.new_key}.{step.new_col}'!r}"
        ) from None
    prior_type = prior_schema.columns[prior_idx].type
    new_type = new_schema.columns[new_idx].type
    if prior_type != new_type and not {prior_type, new_type} <= {"int64", "float64"}:
        raise QueryValidationError(
            f"join key types are incompatible: {prior_type} and {new_type}"
        )

    schema = _derive_step_schema(
        prior_schema,
        new_schema,
        new_table=step.new_key,
        kind=step.kind,
    )
    names = [col.name for col in schema.columns]
    if len(set(names)) != len(names):
        raise QueryValidationError("joined tables produce duplicate column names")
    return schema
def _schema_from_metadata(metadata: Mapping) -> Schema:
    return Schema(
        tuple(
            ColumnSchema(entry["name"], entry["type"], entry["nullable"])
            for entry in metadata["columns"]
        )
    )

"""Execution: run a bound statement over materialised tables.

This stage schedules the row-processing pipeline -- WHERE filter, ORDER BY
sort keys, projection, DISTINCT deduplication, grouping, aggregation,
HAVING, stable sort and LIMIT -- on top of the shared batched evaluator,
and prepares the scans that feed it: column- and row-group-selective reads
of v2 sources and the per-step join-chain assembly.  All semantics live in
the bound expression IR and the join layer; this module only drives them.
"""

from __future__ import annotations

import math
from functools import cmp_to_key
from typing import Any

from .binder import _bind_select, _collect_required_indices
from .errors import QueryValidationError
from .expr import (
    _eval_expr_selection,
    _filter_rows,
    _iter_batches,
    _row_values,
)
from .format import (
    FORMAT_VERSION_PARTITIONED,
    ColumnSchema,
    Schema,
    Table,
    _read_partitioned_table,
    inspect_file,
    inspect_row_groups,
    read_file,
)
from .join import _execute_join
from .parser import _INT64_MAX, _INT64_MIN, _Select
from .pushdown import (
    _extract_pushable,
    _pushed_col_indices,
    _pushable_leaves_by_source,
    _select_row_groups,
    _source_column_spans,
    _source_scan_info,
)
from .resolve import (
    _JoinStep,
    _build_joined_schema,
    _qualify_table,
    _schema_from_metadata,
)


# ---------------------------------------------------------------------------
# Aggregate computation
# ---------------------------------------------------------------------------


def _aggregate_value(
    func: str,
    arg_index: int,
    arg_type: str,
    rows,
    source_columns,
    distinct: bool = False,
):
    if func == "COUNT":
        if arg_index == -1:
            return len(rows)
        col = source_columns[arg_index]
        if not distinct:
            return sum(1 for i in rows if col[i] is not None)
        return len(_distinct_values(col, arg_type, rows))

    col = source_columns[arg_index]
    if distinct:
        values = _distinct_values(col, arg_type, rows)
    else:
        values = [col[i] for i in rows if col[i] is not None]
    if not values:
        return None

    if func == "MIN":
        return min(values)
    if func == "MAX":
        return max(values)
    if func == "SUM":
        if arg_type == "int64":
            # Python integers are unbounded; the int64 result is rejected only
            # when the final total leaves the int64 range.
            total = sum(values)
            if not (_INT64_MIN <= total <= _INT64_MAX):
                raise QueryValidationError("SUM overflowed the int64 range")
            return total
        try:
            total = math.fsum(values)
        except OverflowError:
            raise QueryValidationError("SUM produced a non-finite float64 value") from None
        if not math.isfinite(total):
            raise QueryValidationError("SUM produced a non-finite float64 value")
        return total
    # AVG
    try:
        result = math.fsum(values) / len(values)
    except OverflowError:
        raise QueryValidationError("AVG produced a non-finite float64 value") from None
    if not math.isfinite(result):
        raise QueryValidationError("AVG produced a non-finite float64 value")
    return result


def _distinct_values(col, arg_type: str, rows) -> list:
    """The distinct non-NULL values of ``col`` over ``rows``, first-seen order.

    Equality follows the column's type (the same rule as SELECT DISTINCT):
    float64 0.0 and -0.0 are the same value.  The first occurrence of each
    distinct value is kept as its representative.
    """
    seen: set = set()
    values: list = []
    for i in rows:
        value = col[i]
        if value is None:
            continue
        key = _distinct_key_part(arg_type, value)
        if key not in seen:
            seen.add(key)
            values.append(value)
    return values
def _query_partitioned(
    path: Any, select: _Select, schema: Schema, expected_table
) -> Table:
    """Execute a single-source statement against a v2 (partitioned) file.

    Only the columns the bound plan references are decoded, and only the
    row groups whose statistics do not exclude them.
    """
    bound = _bind_select(select, schema, expected_table=expected_table)
    required = _collect_required_indices(bound)
    groups = inspect_row_groups(path)
    pushed = _extract_pushable(bound["where"])
    selected = _select_row_groups(groups, pushed, _pushed_col_indices(pushed))
    columns = {schema.columns[i].name for i in required}
    table = _read_partitioned_table(path, columns=columns, row_groups=selected)
    return _run_query(table, select, expected_table=expected_table)
def _run_join_chain_partitioned(
    paths, rewritten: _Select, from_key: str, steps, strategy, table_keys
) -> Table:
    """Join chain with at least one v2 (partitioned) source.

    Every source is read restricted to the columns the plan actually
    references (its join keys included); v1 sources keep the historical
    full read.  When every join step is INNER, each v2 source additionally
    reads only the row groups that the top-level AND leaves referencing
    that source alone cannot rule out; a chain containing any OUTER step
    reads every group.  WHERE still runs in full over the joined rows.
    """
    schemas = {}
    versions = {}
    for key in table_keys:
        metadata = inspect_file(paths[key])
        schemas[key] = _schema_from_metadata(metadata)
        versions[key] = metadata["format_version"]
    combined_schema = Schema(
        tuple(
            ColumnSchema(f"{from_key}.{col.name}", col.type, col.nullable)
            for col in schemas[from_key].columns
        )
    )
    for step in steps:
        combined_schema = _build_joined_schema(
            combined_schema, schemas[step.new_key], step
        )
    bound = _bind_select(rewritten, combined_schema, expected_table=None)
    referenced = _collect_required_indices(bound)
    for step in steps:
        referenced.add(combined_schema.index(f"{step.prior_key}.{step.prior_col}"))
        referenced.add(combined_schema.index(f"{step.new_key}.{step.new_col}"))
    referenced_names = {combined_schema.columns[i].name for i in referenced}

    all_inner = all(step.kind == "inner" for step in steps)
    if all_inner:
        spans = _source_column_spans(schemas, table_keys)
        leaves_by_source = _pushable_leaves_by_source(
            bound["where"], spans, table_keys
        )
        group_selection: dict = {}
        for key in table_keys:
            if versions[key] == FORMAT_VERSION_PARTITIONED:
                groups = inspect_row_groups(paths[key])
                info = _source_scan_info(groups, leaves_by_source[key], spans[key])
                group_selection[key] = info["selected_groups"]
    else:
        # An OUTER step can pad a source's rows with NULLs, so no source
        # group can be proven absent from the join result.
        group_selection = {}

    def read_source(key: str) -> Table:
        if versions[key] != FORMAT_VERSION_PARTITIONED:
            return read_file(paths[key])
        required = [
            col.name
            for col in schemas[key].columns
            if f"{key}.{col.name}" in referenced_names
        ]
        selected = group_selection.get(key)
        return _read_partitioned_table(
            paths[key], columns=set(required), row_groups=selected
        ).project(required)

    combined = _qualify_table(read_source(from_key), from_key)
    for step in steps:
        combined = _execute_join_step(
            combined, read_source(step.new_key), step, strategy
        )
    return _run_query(combined, rewritten, expected_table=None)
def _execute_join_step(
    prior: Table,
    new: Table,
    step: _JoinStep,
    strategy: str | None = None,
) -> Table:
    """Execute one validated join step through the shared join layer.

    The combined schema (key existence, key-type compatibility and
    nullability) is derived exactly as the explain plan derives it; the
    selected algorithm only produces the match relation, while expansion
    order, outer NULL padding and result assembly are shared.
    """
    schema = _build_joined_schema(prior.schema, new.schema, step)
    prior_idx = prior.schema.index(f"{step.prior_key}.{step.prior_col}")
    new_idx = new.schema.index(step.new_col)
    return _execute_join(
        prior,
        new,
        prior_idx,
        new_idx,
        schema,
        kind=step.kind,
        strategy=strategy,
    )


def _run_query(table: Table, select: _Select, expected_table="input") -> Table:
    bound = _bind_select(select, table.schema, expected_table)
    source_columns = table._columns
    row_count = table.row_count
    where = bound["where"]

    # The WHERE filter runs batched over the source columns; only rows
    # whose condition is TRUE reach the later stages.
    if where is None:
        selected = list(range(row_count))
    else:
        selected = _filter_rows(where, source_columns, row_count)

    if bound["mode"] == "plain":
        return _run_plain(table, select, bound, selected)
    return _run_aggregate(table, select, bound, selected)


def _run_plain(table: Table, select: _Select, bound, selected: list[int]) -> Table:
    items = bound["items"]
    order_by = bound["order_by"]
    source_columns = table._columns

    out_schema_columns = [
        table.schema.columns[item.col_index]
        if item.kind == "column"
        else ColumnSchema(item.output_name, item.out_type, nullable=item.nullable)
        for item in items
    ]
    out_schema = Schema(out_schema_columns)

    if not bound.get("distinct"):
        # Execution order: WHERE (done by the caller) -> sort keys -> stable
        # sort -> LIMIT -> result expressions, so rows filtered out or cut by
        # LIMIT never evaluate the SELECT expressions.
        if order_by is not None:
            comparator = _make_row_comparator(source_columns, order_by, selected)
            selected = sorted(selected, key=cmp_to_key(comparator))

        if select.limit is not None:
            selected = selected[: select.limit]

        out_columns = _project_items(items, source_columns, selected)
        return Table._from_storage(out_schema, out_columns)

    # DISTINCT: WHERE -> project every surviving input row -> deduplicate the
    # full result rows -> sort -> LIMIT.  Projection happens before the sort
    # so ORDER BY compares deduplicated output values, and before LIMIT so a
    # row LIMIT would cut still surfaces a real division-by-zero/overflow.
    rows = _project_item_rows(items, source_columns, selected)
    rows = _deduplicate_rows(rows, out_schema)

    if order_by is not None:
        comparator = _make_projected_comparator(order_by)
        rows = sorted(rows, key=cmp_to_key(comparator))

    if select.limit is not None:
        rows = rows[: select.limit]

    width = len(items)
    out_columns = [tuple(row[c] for row in rows) for c in range(width)]
    return Table._from_storage(out_schema, out_columns)


def _project_items(items, source_columns, selected) -> list:
    out_columns = []
    for item in items:
        if item.kind == "column":
            out_columns.append(
                tuple(source_columns[item.col_index][i] for i in selected)
            )
        else:  # "expr"
            # Item-major like the historical path: the whole expression
            # column is evaluated (batch by batch) before the next item.
            out_columns.append(
                tuple(_eval_expr_selection(item.expr, source_columns, selected))
            )
    return out_columns


def _project_item_rows(items, source_columns, selected) -> list[tuple]:
    # DISTINCT projection: the historical evaluation order is row-major
    # (every item of a row before the next row), so each batch evaluates
    # every item over its rows and a failure re-runs the batch row by row
    # to surface the exact historical error.
    rows: list[tuple] = []
    for batch in _iter_batches(selected):
        rows.extend(_project_item_batch(items, source_columns, batch))
    return rows


def _project_item_batch(items, source_columns, batch) -> list[tuple]:
    try:
        columns = [
            [source_columns[item.col_index][i] for i in batch]
            if item.kind == "column"
            else item.expr.eval_batch(source_columns, batch, None)
            for item in items
        ]
    except QueryValidationError:
        # Reproduce the historical row-major error for this batch.
        return [
            tuple(
                source_columns[item.col_index][i]
                if item.kind == "column"
                else item.expr.eval(_row_values(source_columns, i), None)
                for item in items
            )
            for i in batch
        ]
    return [tuple(column[k] for column in columns) for k in range(len(batch))]


def _deduplicate_rows(rows: list[tuple], schema: Schema) -> list[tuple]:
    """Keep the first occurrence of each distinct result row.

    Equality follows the result schema column by column: NULLs compare equal
    to each other but never to a non-NULL value, bool/utf8/numeric keep
    their existing semantics, and float64 0.0 and -0.0 compare equal.
    """
    seen: set[tuple] = set()
    unique: list[tuple] = []
    for row in rows:
        key = tuple(
            _distinct_key_part(schema.columns[c].type, value)
            for c, value in enumerate(row)
        )
        if key not in seen:
            seen.add(key)
            unique.append(row)
    return unique


def _distinct_key_part(type_name: str, value):
    if value is None:
        return (False,)
    if type_name == "float64":
        # 0.0 and -0.0 are the same distinct value; the wrapper also keeps a
        # float from ever colliding with an int64 part of the same number.
        return (True, 0.0 if value == 0 else value)
    return (True, value)


def _make_projected_comparator(order_by: tuple[tuple, ...]):
    def compare(a: tuple, b: tuple) -> int:
        for entry in order_by:
            col_index = entry[1]
            c = _compare_scalar(a[col_index], b[col_index], entry[2], entry[3])
            if c:
                return c
        return 0

    return compare


def _run_aggregate(table: Table, select: _Select, bound, selected: list[int]) -> Table:
    group_indices = bound["group_indices"]
    bound_items = bound["items"]
    all_aggs = bound["aggregates"]
    having = bound["having"]
    order_by = bound["order_by"]
    source_columns = table._columns

    out_schema = Schema(
        [
            ColumnSchema(item.output_name, item.out_type, nullable=item.nullable)
            for item in bound_items
        ]
    )

    if group_indices:
        groups = _build_groups(selected, source_columns, group_indices)
    else:
        # Without GROUP BY the whole filtered stream is the single group; an
        # empty stream still produces the one all-NULL/COUNT-0 row.
        groups = [tuple(selected)]

    # Projected aggregates are the same _BoundItem instances as the registry
    # entries (frozen, appended by reference), so identity gives their slots.
    agg_slot_by_id = {id(agg): i for i, agg in enumerate(all_aggs)}

    # One materialised SELECT tuple per group that survives the post-grouping
    # HAVING filter; the original first-row group order is preserved.
    materialised: list[tuple] = []
    for rows in groups:
        agg_values = tuple(
            _aggregate_value(
                agg.func, agg.arg_index, agg.arg_type, rows, source_columns,
                agg.distinct,
            )
            for agg in all_aggs
        )
        if having is not None and _eval_having(having, source_columns, rows, agg_values) is not True:
            continue
        values = []
        for item in bound_items:
            if item.kind == "column":
                values.append(source_columns[item.col_index][rows[0]])
            else:
                values.append(agg_values[agg_slot_by_id[id(item)]])
        materialised.append(tuple(values))

    if order_by is not None:
        comparator = _make_tuple_comparator(materialised, order_by)
        order = sorted(range(len(materialised)), key=cmp_to_key(comparator))
    else:
        order = list(range(len(materialised)))

    if select.limit is not None:
        order = order[: select.limit]

    width_out = len(bound_items)
    out_columns = [tuple(materialised[r][c] for r in order) for c in range(width_out)]
    return Table._from_storage(out_schema, out_columns)


def _eval_having(
    node: _Expr,
    source_columns: tuple[tuple, ...],
    rows: tuple[int, ...],
    agg_values: tuple,
) -> bool | None:
    """Three-valued evaluation of a bound HAVING condition for one group.

    The bound tree is the same expression IR as WHERE; grouping columns
    are read from the group's first selected row, which is always present
    for a group node (the global aggregate case carries no columns).
    """
    row = _row_values(source_columns, rows[0]) if rows else ()
    return node.eval(row, agg_values)


def _build_groups(
    selected: list[int],
    source_columns: tuple[tuple, ...],
    group_indices: tuple[int, ...],
) -> list[tuple[int, ...]]:
    groups: dict[tuple, list[int]] = {}
    order: list[tuple] = []
    for row_index in selected:
        key = tuple(source_columns[col][row_index] for col in group_indices)
        bucket = groups.get(key)
        if bucket is None:
            bucket = []
            groups[key] = bucket
            order.append(key)
        bucket.append(row_index)
    return [tuple(groups[key]) for key in order]
def _make_row_comparator(
    source_columns: tuple[tuple, ...],
    order_by: tuple[tuple, ...],
    selected: list[int],
):
    # Sort keys are computed for every row that passed WHERE, before the
    # stable sort and LIMIT; expression keys (SELECT aliases) are evaluated
    # here, batch by batch over the surviving rows, so their errors surface
    # even for rows LIMIT would cut.
    key_sources: list[tuple] = []
    for entry in order_by:
        if entry[0] == "col":
            key_sources.append((source_columns[entry[1]], entry[2], entry[3]))
        else:  # "expr"
            values = dict(
                zip(selected, _eval_expr_selection(entry[1], source_columns, selected))
            )
            key_sources.append((values, entry[2], entry[3]))

    def compare(a: int, b: int) -> int:
        for values, descending, nulls_first in key_sources:
            c = _compare_scalar(values[a], values[b], descending, nulls_first)
            if c:
                return c
        return 0

    return compare


def _make_tuple_comparator(
    rows: list[tuple],
    order_by: tuple[tuple[int, bool, bool], ...],
):
    def compare(a: int, b: int) -> int:
        for col_index, descending, nulls_first in order_by:
            va = rows[a][col_index]
            vb = rows[b][col_index]
            c = _compare_scalar(va, vb, descending, nulls_first)
            if c:
                return c
        return 0

    return compare


def _compare_scalar(va, vb, descending: bool, nulls_first: bool) -> int:
    if va is None or vb is None:
        if va is None and vb is None:
            return 0
        # NULL placement follows NULLS FIRST / NULLS LAST alone; the
        # default (and the explicit LAST spelling) keeps NULLs at the
        # end for both ASC and DESC, so DESC must not flip this part.
        none_before = -1 if nulls_first else 1
        return none_before if va is None else -none_before
    c = (va > vb) - (va < vb)
    return -c if descending else c

"""Explain-plan construction.

Renders the bound statement -- the very same bound dict the executor runs
-- as the JSON-serialisable operator tree: Scan operators per referenced
source (with the v2 pushdown fields where eligible), one Join operator per
step, then Filter / Aggregate / Having / Project / Distinct / Sort / Limit
exactly as execution orders them.  Nothing here reads files; the caller
supplies the source metadata it already inspected.
"""

from __future__ import annotations

from collections.abc import Mapping

from .binder import _collect_required_indices
from .expr import _Expr
from .format import Schema
from .join import _strategy_label
from .parser import _Select
from .resolve import _JoinStep


def _source_description(key: str, metadata: Mapping) -> dict:
    return {
        "name": key,
        "row_count": metadata["row_count"],
        "columns": [
            {
                "name": entry["name"],
                "type": entry["type"],
                "nullable": entry["nullable"],
            }
            for entry in metadata["columns"]
        ],
    }
def _expr_json(node: _Expr) -> dict:
    """Render a bound expression as its explain-plan JSON tree.

    Every bound node -- WHERE conditions, SELECT expressions and the HAVING
    tree including its aggregate leaves -- owns its rendering via
    :meth:`_Expr.to_json`, so plan JSON and the executable expression can
    never disagree.
    """
    return node.to_json()


def _aggregate_json(item, schema: Schema) -> dict:
    """Render one bound aggregate of the Aggregate operator as JSON.

    DISTINCT aggregates gain a ``distinct: true`` field; plain aggregates
    keep the historical three-field shape.
    """
    entry = {
        "function": item.func,
        "argument": (
            None if item.arg_index < 0 else schema.columns[item.arg_index].name
        ),
        "output": item.output_name,
    }
    if item.distinct:
        entry["distinct"] = True
    return entry


def _build_explain(
    sources: tuple,
    schema: Schema,
    select: _Select,
    bound: Mapping,
    steps: tuple[_JoinStep, ...] = (),
    strategy: str | None = None,
    scan_extras: Mapping | None = None,
) -> dict:
    referenced = _collect_required_indices(bound)
    for step in steps:
        # The ON keys feed the join even when neither is projected.
        referenced.add(schema.index(f"{step.prior_key}.{step.prior_col}"))
        referenced.add(schema.index(f"{step.new_key}.{step.new_col}"))

    operators: list = []
    referenced_names = {schema.columns[i].name for i in referenced}
    for key, _metadata, source_schema in sources:
        if not steps:
            required = [col.name for col in schema.columns if col.name in referenced_names]
        else:
            prefix = f"{key}."
            required = [
                col.name
                for col in source_schema.columns
                if f"{prefix}{col.name}" in referenced_names
            ]
        scan_operator = {"operator": "Scan", "source": key, "required_columns": required}
        if scan_extras is not None and key in scan_extras:
            # An eligible v2 (row-group-partitioned) scan reports the
            # statistics pushdown right after required_columns: total /
            # selected row groups and the pushed condition tree (null when
            # nothing was pushed).  v1 scans and scans of chains containing
            # an OUTER step keep their historical three-field shape.
            scan_operator.update(scan_extras[key])
        operators.append(scan_operator)

    # One Join operator per step, in FROM/JOIN order; each reports the two
    # qualified ON keys normalised to prior-table (intermediate) left and
    # freshly introduced table right.  An explicitly requested strategy is
    # reported on every Join operator; the implicit path (join_strategy
    # omitted) keeps the operator shape with no strategy field.
    for step in steps:
        join_operator = {
            "operator": "Join",
            "type": step.kind.upper(),
            "left": {"table": step.prior_key, "column": step.prior_col},
            "right": {"table": step.new_key, "column": step.new_col},
        }
        if strategy is not None:
            join_operator["strategy"] = _strategy_label(strategy)
        operators.append(join_operator)

    if bound["where"] is not None:
        operators.append({"operator": "Filter", "condition": _expr_json(bound["where"])})

    if bound["mode"] == "aggregate":
        # The Aggregate node computes every distinct aggregate the SELECT,
        # ORDER BY or HAVING needs, in first-reference order.  Only
        # DISTINCT aggregates carry a "distinct" field; plain aggregate
        # entries keep their historical shape.
        operators.append(
            {
                "operator": "Aggregate",
                "group_keys": [
                    schema.columns[index].name for index in bound["group_indices"]
                ],
                "aggregates": [
                    _aggregate_json(item, schema)
                    for item in bound["aggregates"]
                ],
            }
        )
        if bound["having"] is not None:
            operators.append(
                {
                    "operator": "Having",
                    "condition": _expr_json(bound["having"]),
                }
            )

    projections = []
    for item in bound["items"]:
        if item.kind == "column":
            expression = {"kind": "column", "name": schema.columns[item.col_index].name}
        elif item.kind == "agg":
            expression = {
                "kind": "aggregate",
                "function": item.func,
                "argument": (
                    None
                    if item.arg_index < 0
                    else schema.columns[item.arg_index].name
                ),
            }
            if item.distinct:
                expression["distinct"] = True
        else:  # "expr"
            expression = _expr_json(item.expr)
        projections.append({"expression": expression, "output": item.output_name})
    project_operator = {"operator": "Project", "expressions": projections}

    if bound.get("distinct"):
        # DISTINCT evaluates the projection right after the scan/join/filter
        # stages, then deduplicates the result rows before Sort and Limit.
        operators.append(project_operator)
        operators.append(
            {
                "operator": "Distinct",
                "keys": [item.output_name for item in bound["items"]],
            }
        )
        if bound["order_by"] is not None:
            keys = []
            for entry in bound["order_by"]:
                # DISTINCT ORDER BY entries index projected output columns.
                name = bound["items"][entry[1]].output_name
                keys.append(
                    {
                        "column": name,
                        "direction": "DESC" if entry[2] else "ASC",
                        "nulls": "FIRST" if entry[3] else "LAST",
                    }
                )
            operators.append({"operator": "Sort", "keys": keys})
        if select.limit is not None:
            operators.append({"operator": "Limit", "count": select.limit})
    else:
        if bound["order_by"] is not None:
            alias_by_expr = {
                id(item.expr): item.output_name
                for item in bound["items"]
                if item.kind == "expr"
            }
            keys = []
            for entry in bound["order_by"]:
                if entry[0] == "col":
                    name = schema.columns[entry[1]].name
                    descending, nulls_first = entry[2], entry[3]
                elif entry[0] == "expr":
                    name = alias_by_expr[id(entry[1])]
                    descending, nulls_first = entry[2], entry[3]
                else:  # aggregate-query ORDER BY indexes a selected output column
                    name = bound["items"][entry[0]].output_name
                    descending, nulls_first = entry[1], entry[2]
                keys.append(
                    {
                        "column": name,
                        "direction": "DESC" if descending else "ASC",
                        "nulls": "FIRST" if nulls_first else "LAST",
                    }
                )
            operators.append({"operator": "Sort", "keys": keys})

        if select.limit is not None:
            operators.append({"operator": "Limit", "count": select.limit})
        operators.append(project_operator)

    output = [
        {
            "name": item.output_name,
            "type": item.out_type,
            "nullable": item.nullable,
        }
        for item in bound["items"]
    ]

    return {
        "sources": [_source_description(key, metadata) for key, metadata, _ in sources],
        "operators": operators,
        "output": output,
    }

"""Self-describing columnar file format.

Public API:

* :class:`ColumnSchema` / :class:`Schema` / :class:`Table` -- in-memory model
* :func:`write_file` -- deterministic, atomic write of the v1 format
* :func:`write_partitioned_file` -- deterministic, atomic write of the
  row-group-partitioned v2 format
* :func:`read_file` -- strict, validating read with optional projection
  (both format versions)
* :func:`inspect_file` -- metadata-only read (both format versions)
* :func:`inspect_row_groups` -- metadata-only per-row-group statistics
* :class:`ColumnarFormatError` -- raised for every malformed-file condition

File layout (little-endian)::

    b"CAEF"            magic
    uint8              format version (1 or 2)
    uint32             header byte length
    <header bytes>     UTF-8 JSON, schema + per-column stats/chunk pointers
    <data section>     raw concatenated column payloads, or zlib of the same
    uint32             CRC-32 of every preceding byte   (version 1 only)
    b"END1"            end marker

Version 1 stores one chunk per column and optionally zlib-compresses the
whole data section.  Version 2 (written by :func:`write_partitioned_file`)
splits the rows into consecutive row groups of a fixed size; every group
carries its row count and per-column ``null_count`` / ``min`` / ``max``
statistics, and every (group, column) block is stored -- and optionally
zlib-compressed -- independently, so a single block can be located,
checksummed, decompressed and decoded without touching the others.  The v2
trailer is the bare ``END1`` marker; integrity comes from the declared
sizes and the per-block CRC-32 checksums of the blocks actually read.

The same schema, values and options always produce identical bytes: the JSON
header uses a fixed key order and compact separators, there are no timestamps,
and zlib is invoked with a fixed level.
"""

from __future__ import annotations

import json
import os
import struct
import tempfile
import zlib
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any

__all__ = [
    "FORMAT_VERSION",
    "FORMAT_VERSION_PARTITIONED",
    "ColumnarFormatError",
    "ColumnSchema",
    "Schema",
    "Table",
    "write_file",
    "write_partitioned_file",
    "read_file",
    "inspect_file",
    "inspect_row_groups",
]

FORMAT_VERSION = 1
# Version 2: the row-group-partitioned layout written by
# ``write_partitioned_file``.  Readers dispatch on the version byte.
FORMAT_VERSION_PARTITIONED = 2

_MAGIC = b"CAEF"
_FOOTER_MARKER = b"END1"
_TYPE_NAMES = ("bool", "int64", "float64", "utf8")
_ENCODING_NAMES = ("plain", "dictionary")
_COMPRESSION_NAMES = ("none", "zlib")
_HEADER_KEYS = frozenset(
    ("compression", "row_count", "data_length", "data_crc32", "uncompressed_length", "columns")
)
_COLUMN_KEYS = frozenset(
    ("name", "type", "nullable", "encoding", "offset", "length", "crc32",
     "null_count", "min", "max")
)
_V2_HEADER_KEYS = frozenset(
    ("compression", "row_count", "row_group_size", "data_length", "columns", "row_groups")
)
_V2_COLUMN_KEYS = frozenset(("name", "type", "nullable", "encoding"))
_V2_GROUP_KEYS = frozenset(("row_count", "columns"))
_V2_BLOCK_KEYS = frozenset(
    ("offset", "length", "crc32", "uncompressed_length", "null_count", "min", "max")
)
_PREFIX_LEN = 9  # magic(4) + version(1) + header length uint32
_FOOTER_LEN = 8  # crc32 uint32 + marker
_V2_TRAILER_LEN = 4  # bare end marker
_MAX_HEADER_BYTES = 256 * 1024 * 1024


class ColumnarFormatError(Exception):
    """Raised when a columnar file is structurally invalid or unsupported."""


# ---------------------------------------------------------------------------
# In-memory model
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class ColumnSchema:
    """One column: a non-empty unique Unicode ``name``, a type and nullability."""

    name: str
    type: str
    nullable: bool = False

    def __post_init__(self) -> None:
        if not isinstance(self.name, str) or not self.name:
            raise ValueError("column name must be a non-empty string")
        try:
            self.name.encode("utf-8")
        except UnicodeEncodeError:
            raise ValueError("column name must contain valid Unicode scalars") from None
        if self.type not in _TYPE_NAMES:
            raise ValueError(f"unsupported column type: {self.type!r}")
        if not isinstance(self.nullable, bool):
            raise ValueError("nullable must be a bool")


@dataclass(frozen=True)
class Schema:
    """An ordered, non-empty collection of :class:`ColumnSchema`."""

    columns: tuple[ColumnSchema, ...]

    def __init__(self, columns: Sequence[ColumnSchema]):
        cols = tuple(columns)
        if not cols:
            raise ValueError("schema must contain at least one column")
        for col in cols:
            if not isinstance(col, ColumnSchema):
                raise ValueError("schema entries must be ColumnSchema instances")
        seen: set[str] = set()
        for col in cols:
            if col.name in seen:
                raise ValueError(f"duplicate column name: {col.name!r}")
            seen.add(col.name)
        object.__setattr__(self, "columns", cols)

    @property
    def names(self) -> tuple[str, ...]:
        return tuple(col.name for col in self.columns)

    def index(self, name: str) -> int:
        for i, col in enumerate(self.columns):
            if col.name == name:
                return i
        raise KeyError(name)


class Table:
    """A schema together with equal-length, column-oriented Python lists."""

    def __init__(self, schema: Schema, columns: Mapping[str, Sequence] | Sequence[Sequence]):
        if not isinstance(schema, Schema):
            raise TypeError("schema must be a Schema instance")
        aligned = _align_columns(schema, columns)
        row_count = _validate_columns(schema, aligned)
        self.schema = schema
        self._row_count = row_count
        self._columns = tuple(tuple(col) for col in aligned)

    @classmethod
    def _from_storage(cls, schema: Schema, columns: Sequence[Sequence]) -> "Table":
        """Build without re-validating (used by the decoder)."""
        obj = cls.__new__(cls)
        obj.schema = schema
        obj._row_count = len(columns[0]) if columns else 0
        obj._columns = tuple(tuple(col) for col in columns)
        return obj

    @property
    def row_count(self) -> int:
        return self._row_count

    @property
    def column_names(self) -> tuple[str, ...]:
        return self.schema.names

    def column(self, name: str) -> list:
        """Return a fresh list of the named column's values."""
        return list(self._columns[self.schema.index(name)])

    @property
    def columns(self) -> dict[str, list]:
        """Column name to value list, in schema order."""
        return {name: list(self._columns[i]) for i, name in enumerate(self.schema.names)}

    def project(self, names: Sequence[str]) -> "Table":
        """Return a table restricted to ``names``, in the requested order.

        Unknown names raise :class:`KeyError`; repeated names raise
        :class:`ValueError`.
        """
        if isinstance(names, str):
            raise ValueError("project names must be a sequence of strings, not a single string")
        requested = tuple(names)
        if len(set(requested)) != len(requested):
            raise ValueError("projection contains duplicate column names")
        indices = []
        for name in requested:
            indices.append(self.schema.index(name))  # KeyError on unknown name
        sub_schema = Schema([self.schema.columns[i] for i in indices])
        sub_cols = [self._columns[i] for i in indices]
        return Table._from_storage(sub_schema, sub_cols)


def _align_columns(
    schema: Schema, columns: Mapping[str, Sequence] | Sequence[Sequence]
) -> list[Sequence]:
    if isinstance(columns, Mapping):
        missing = [name for name in schema.names if name not in columns]
        if missing:
            raise ValueError(f"missing column(s): {', '.join(missing)!r}")
        extra = [name for name in columns if name not in set(schema.names)]
        if extra:
            raise ValueError(f"unexpected column(s): {', '.join(map(str, extra))!r}")
        return [columns[name] for name in schema.names]
    if isinstance(columns, Sequence) and not isinstance(columns, (str, bytes)):
        if len(columns) != len(schema.columns):
            raise ValueError(
                f"expected {len(schema.columns)} columns, got {len(columns)}"
            )
        return list(columns)
    raise TypeError("columns must be a mapping or a sequence aligned to the schema")


def _validate_columns(schema: Schema, columns: Sequence[Sequence]) -> int:
    """Check shape, nullability, per-value Python types and float finiteness."""
    row_count: int | None = None
    for col, raw in zip(schema.columns, columns):
        try:
            values = list(raw)
        except TypeError:
            raise ValueError(f"column {col.name!r} is not a sequence") from None
        if row_count is None:
            row_count = len(values)
        elif len(values) != row_count:
            raise ValueError(
                f"column {col.name!r} has {len(values)} rows, expected {row_count}"
            )
        for position, value in enumerate(values):
            where = f"column {col.name!r} row {position}"
            if value is None:
                if not col.nullable:
                    raise ValueError(f"{where}: NULL in non-nullable column")
                continue
            if col.type == "bool":
                if not isinstance(value, bool):
                    raise ValueError(f"{where}: expected bool, got {type(value).__name__}")
            elif col.type == "int64":
                if isinstance(value, bool) or not isinstance(value, int):
                    raise ValueError(f"{where}: expected int64, got {type(value).__name__}")
                if not (-(2**63) <= value <= 2**63 - 1):
                    raise ValueError(f"{where}: value outside int64 range")
            elif col.type == "float64":
                if isinstance(value, bool) or not isinstance(value, float):
                    raise ValueError(f"{where}: expected float64, got {type(value).__name__}")
                if value != value or value in (float("inf"), float("-inf")):
                    raise ValueError(f"{where}: float64 must be finite (no NaN or infinity)")
            elif col.type == "utf8":
                if not isinstance(value, str):
                    raise ValueError(f"{where}: expected utf8 string, got {type(value).__name__}")
                try:
                    value.encode("utf-8")
                except UnicodeEncodeError:
                    raise ValueError(f"{where}: string is not valid UTF-8 Unicode") from None
    assert row_count is not None
    return row_count


# ---------------------------------------------------------------------------
# Encoding
# ---------------------------------------------------------------------------


def _pack_bits(flags: Sequence[bool]) -> bytes:
    out = bytearray((len(flags) + 7) // 8)
    for i, flag in enumerate(flags):
        if flag:
            out[i >> 3] |= 1 << (i & 7)
    return bytes(out)


def _check_padding(bits: bytes, count: int, what: str) -> None:
    if count % 8:
        unused = bits[-1] >> (count % 8)
        if unused:
            raise ColumnarFormatError(f"non-zero padding bits in {what}")


def _encode_payload(
    col: ColumnSchema, values: Sequence, use_dictionary: bool
) -> tuple[bytes, int, Any, Any]:
    n = len(values)
    null_count = 0
    minimum: Any = None
    maximum: Any = None
    validity = bytearray((n + 7) // 8) if col.nullable else None

    if col.type == "bool":
        flags: list[bool] = []
        for i, value in enumerate(values):
            if value is None:
                flags.append(False)
                null_count += 1
                continue
            if validity is not None:
                validity[i >> 3] |= 1 << (i & 7)
            flags.append(value)
            if minimum is None or value < minimum:
                minimum = value
            if maximum is None or value > maximum:
                maximum = value
        body = _pack_bits(flags)
    elif col.type == "int64":
        buf = bytearray()
        for i, value in enumerate(values):
            if value is None:
                buf.extend(b"\x00" * 8)
                null_count += 1
                continue
            if validity is not None:
                validity[i >> 3] |= 1 << (i & 7)
            buf.extend(struct.pack("<q", value))
            if minimum is None or value < minimum:
                minimum = value
            if maximum is None or value > maximum:
                maximum = value
        body = bytes(buf)
    elif col.type == "float64":
        buf = bytearray()
        for i, value in enumerate(values):
            if value is None:
                buf.extend(b"\x00" * 8)
                null_count += 1
                continue
            if validity is not None:
                validity[i >> 3] |= 1 << (i & 7)
            buf.extend(struct.pack("<d", value))
            if minimum is None or value < minimum:
                minimum = value
            if maximum is None or value > maximum:
                maximum = value
        body = bytes(buf)
    else:  # utf8
        if use_dictionary:
            dictionary: list[str] = []
            dictionary_index: dict[str, int] = {}
            indices = bytearray()
            for i, value in enumerate(values):
                if value is None:
                    indices.extend(struct.pack("<i", -1))
                    null_count += 1
                    continue
                if validity is not None:
                    validity[i >> 3] |= 1 << (i & 7)
                idx = dictionary_index.get(value)
                if idx is None:
                    # Dictionary ids follow first-occurrence order.
                    idx = len(dictionary)
                    dictionary_index[value] = idx
                    dictionary.append(value)
                indices.extend(struct.pack("<i", idx))
                if minimum is None or value < minimum:
                    minimum = value
                if maximum is None or value > maximum:
                    maximum = value
            body = (
                struct.pack("<I", len(dictionary))
                + _encode_utf8_strings(dictionary)
                + bytes(indices)
            )
        else:
            ordered: list[str] = []
            for i, value in enumerate(values):
                if value is None:
                    ordered.append("")
                    null_count += 1
                    continue
                if validity is not None:
                    validity[i >> 3] |= 1 << (i & 7)
                ordered.append(value)
                if minimum is None or value < minimum:
                    minimum = value
                if maximum is None or value > maximum:
                    maximum = value
            body = _encode_utf8_strings(ordered)

    payload = (bytes(validity) if validity is not None else b"") + body
    return payload, null_count, minimum, maximum


def _encode_utf8_strings(strings: Sequence[str]) -> bytes:
    offsets = bytearray()
    blob = bytearray()
    cursor = 0
    offsets.extend(struct.pack("<I", 0))
    for value in strings:
        raw = value.encode("utf-8")
        cursor += len(raw)
        blob.extend(raw)
        offsets.extend(struct.pack("<I", cursor))
    return bytes(offsets) + bytes(blob)


# ---------------------------------------------------------------------------
# Decoding
# ---------------------------------------------------------------------------


def _decode_column(
    col: ColumnSchema, encoding: str, row_count: int, payload: bytes
) -> list:
    cursor = 0
    validity: bytes | None = None
    if col.nullable:
        size = (row_count + 7) // 8
        if len(payload) < cursor + size:
            raise ColumnarFormatError(f"truncated validity bitmap for {col.name!r}")
        validity = payload[cursor : cursor + size]
        _check_padding(validity, row_count, f"validity bitmap of {col.name!r}")
        cursor += size
    body = payload[cursor:]

    if col.type == "bool":
        size = (row_count + 7) // 8
        if len(body) != size:
            raise ColumnarFormatError(f"bad bool payload length for {col.name!r}")
        _check_padding(body, row_count, f"bool payload of {col.name!r}")
        values = [
            bool((body[i >> 3] >> (i & 7)) & 1) for i in range(row_count)
        ]
    elif col.type == "int64":
        if len(body) != 8 * row_count:
            raise ColumnarFormatError(f"bad int64 payload length for {col.name!r}")
        values = list(struct.unpack(f"<{row_count}q", body)) if row_count else []
    elif col.type == "float64":
        if len(body) != 8 * row_count:
            raise ColumnarFormatError(f"bad float64 payload length for {col.name!r}")
        values = list(struct.unpack(f"<{row_count}d", body)) if row_count else []
        for i, value in enumerate(values):
            if value != value or value in (float("inf"), float("-inf")):
                raise ColumnarFormatError(
                    f"non-finite float64 stored in {col.name!r} row {i}"
                )
    elif encoding == "dictionary":
        values = _decode_dict_utf8(col, row_count, body, validity)
    else:
        values = _decode_plain_utf8(col, row_count, body)

    if validity is not None:
        for i in range(row_count):
            if not ((validity[i >> 3] >> (i & 7)) & 1):
                values[i] = None
    return values


def _decode_utf8_blob(col: ColumnSchema, body: bytes, count: int, *, what: str) -> list[str]:
    offset_bytes = 4 * (count + 1)
    if len(body) < offset_bytes:
        raise ColumnarFormatError(f"truncated {what} offsets for {col.name!r}")
    offsets = struct.unpack(f"<{count + 1}I", body[:offset_bytes])
    blob = body[offset_bytes:]
    if offsets[0] != 0:
        raise ColumnarFormatError(f"{what} offsets must start at 0 for {col.name!r}")
    for prev, nxt in zip(offsets, offsets[1:]):
        if nxt < prev:
            raise ColumnarFormatError(f"non-monotonic {what} offsets for {col.name!r}")
    if offsets[-1] != len(blob):
        raise ColumnarFormatError(f"{what} byte length mismatch for {col.name!r}")
    strings = []
    for i in range(count):
        raw = blob[offsets[i] : offsets[i + 1]]
        try:
            strings.append(raw.decode("utf-8"))
        except UnicodeDecodeError:
            raise ColumnarFormatError(
                f"invalid UTF-8 in {what} entry {i} of {col.name!r}"
            ) from None
    return strings


def _decode_plain_utf8(col: ColumnSchema, row_count: int, body: bytes) -> list[str]:
    return _decode_utf8_blob(col, body, row_count, what="utf8")


def _decode_dict_utf8(
    col: ColumnSchema, row_count: int, body: bytes, validity: bytes | None
) -> list[str]:
    if len(body) < 4:
        raise ColumnarFormatError(f"truncated dictionary header for {col.name!r}")
    (dict_size,) = struct.unpack("<I", body[:4])
    rest = body[4:]
    offset_bytes = 4 * (dict_size + 1)
    # Split dictionary section from the trailing row indices.
    if len(rest) < offset_bytes:
        raise ColumnarFormatError(f"truncated dictionary offsets for {col.name!r}")
    tentative_offsets = struct.unpack(f"<{dict_size + 1}I", rest[:offset_bytes])
    dict_section_len = offset_bytes + tentative_offsets[-1]
    if dict_section_len > len(rest) - 4 * row_count:
        raise ColumnarFormatError(f"dictionary overruns payload for {col.name!r}")
    dictionary = _decode_utf8_blob(
        col, rest[:dict_section_len], dict_size, what="dictionary"
    )
    index_bytes = rest[dict_section_len:]
    if len(index_bytes) != 4 * row_count:
        raise ColumnarFormatError(f"bad dictionary index length for {col.name!r}")
    raw_indices = struct.unpack(f"<{row_count}i", index_bytes) if row_count else ()
    values: list[str] = []
    for i, idx in enumerate(raw_indices):
        is_valid = validity is None or bool((validity[i >> 3] >> (i & 7)) & 1)
        if idx == -1:
            if not col.nullable or is_valid:
                raise ColumnarFormatError(
                    f"NULL dictionary index contradicts validity in {col.name!r} row {i}"
                )
            values.append("")  # replaced with None via validity bitmap below
        elif not 0 <= idx < dict_size:
            raise ColumnarFormatError(
                f"dictionary index {idx} out of range in {col.name!r} row {i}"
            )
        else:
            if not is_valid:
                raise ColumnarFormatError(
                    f"valid dictionary index in NULL slot of {col.name!r} row {i}"
                )
            values.append(dictionary[idx])
    return values


# ---------------------------------------------------------------------------
# Header (JSON metadata)
# ---------------------------------------------------------------------------


def _stats_json(value: Any) -> Any:
    return value


def _build_header(
    table: Table,
    compression: str,
    data_section: bytes,
    raw_section: bytes,
    chunk_info: Sequence[dict],
) -> dict:
    return {
        "compression": compression,
        "row_count": table.row_count,
        "data_length": len(data_section),
        "data_crc32": zlib.crc32(data_section) & 0xFFFFFFFF,
        "uncompressed_length": len(raw_section),
        "columns": list(chunk_info),
    }


def _dump_json(header: dict) -> bytes:
    return json.dumps(
        header, separators=(",", ":"), ensure_ascii=False, allow_nan=False
    ).encode("utf-8")


def _reject_duplicate_keys(pairs: Sequence[tuple[str, Any]]) -> dict:
    seen: set[str] = set()
    for key, _ in pairs:
        if key in seen:
            raise ColumnarFormatError(f"duplicate JSON key in header: {key!r}")
        seen.add(key)
    return dict(pairs)


def _reject_json_constant(value: str):
    raise ColumnarFormatError(f"illegal JSON constant in header: {value}")


def _is_uint32(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and 0 <= value <= 0xFFFFFFFF


def _is_nonneg_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _validate_header(header: Any) -> dict:
    if not isinstance(header, dict):
        raise ColumnarFormatError("header must be a JSON object")
    unknown = set(header) - _HEADER_KEYS
    if unknown:
        raise ColumnarFormatError(f"unknown header key(s): {sorted(unknown)!r}")
    compression = header.get("compression")
    if compression not in _COMPRESSION_NAMES:
        raise ColumnarFormatError(f"unknown compression in header: {compression!r}")
    row_count = header.get("row_count")
    if not _is_nonneg_int(row_count):
        raise ColumnarFormatError("header row_count must be a non-negative integer")
    data_length = header.get("data_length")
    if not _is_nonneg_int(data_length):
        raise ColumnarFormatError("header data_length must be a non-negative integer")
    data_crc = header.get("data_crc32")
    if not _is_uint32(data_crc):
        raise ColumnarFormatError("header data_crc32 must be a uint32")
    uncompressed_length = header.get("uncompressed_length")
    if not _is_nonneg_int(uncompressed_length):
        raise ColumnarFormatError("header uncompressed_length must be a non-negative integer")
    entries = header.get("columns")
    if not isinstance(entries, list) or not entries:
        raise ColumnarFormatError("header must list at least one column")

    seen: set[str] = set()
    next_offset = 0
    for pos, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise ColumnarFormatError(f"column header #{pos} must be an object")
        unknown_col = set(entry) - _COLUMN_KEYS
        if unknown_col:
            raise ColumnarFormatError(
                f"column header #{pos}: unknown key(s) {sorted(unknown_col)!r}"
            )
        name = entry.get("name")
        if not isinstance(name, str) or not name:
            raise ColumnarFormatError(f"column header #{pos}: name must be a non-empty string")
        if name in seen:
            raise ColumnarFormatError(f"duplicate column in header: {name!r}")
        seen.add(name)
        col_type = entry.get("type")
        if col_type not in _TYPE_NAMES:
            raise ColumnarFormatError(f"column {name!r}: unknown type {col_type!r}")
        nullable = entry.get("nullable")
        if not isinstance(nullable, bool):
            raise ColumnarFormatError(f"column {name!r}: nullable must be true or false")
        encoding = entry.get("encoding")
        if encoding not in _ENCODING_NAMES:
            raise ColumnarFormatError(f"column {name!r}: unknown encoding {encoding!r}")
        if encoding == "dictionary" and col_type != "utf8":
            raise ColumnarFormatError(f"column {name!r}: dictionary encoding requires utf8")
        for key in ("offset", "length", "null_count"):
            if not _is_nonneg_int(entry.get(key)):
                raise ColumnarFormatError(f"column {name!r}: {key} must be a non-negative integer")
        if not _is_uint32(entry.get("crc32")):
            raise ColumnarFormatError(f"column {name!r}: crc32 must be a uint32")
        if "min" not in entry or "max" not in entry:
            raise ColumnarFormatError(f"column {name!r}: min and max keys are required")
        if entry["offset"] != next_offset:
            raise ColumnarFormatError(f"column {name!r}: chunks are not contiguous")
        next_offset += entry["length"]
        null_count = entry["null_count"]
        if null_count > row_count:
            raise ColumnarFormatError(f"column {name!r}: null_count exceeds row_count")
        if not nullable and null_count:
            raise ColumnarFormatError(f"column {name!r}: NULL count set for non-nullable column")
        _validate_stats(entry, col_type, row_count, null_count)
    if next_offset != uncompressed_length:
        raise ColumnarFormatError("declared uncompressed length does not match column chunks")
    return header


def _validate_stats(
    entry: dict, col_type: str, row_count: int, null_count: int
) -> None:
    name = entry["name"]
    minimum = entry.get("min")
    maximum = entry.get("max")
    if null_count == row_count:
        if minimum is not None or maximum is not None:
            raise ColumnarFormatError(f"column {name!r}: all-NULL column needs null min/max")
        return
    if minimum is None or maximum is None:
        raise ColumnarFormatError(f"column {name!r}: min and max must both be present")
    if col_type == "bool":
        if not isinstance(minimum, bool) or not isinstance(maximum, bool):
            raise ColumnarFormatError(f"column {name!r}: bool stats must be booleans")
    elif col_type == "int64":
        if not _is_int64_json(minimum) or not _is_int64_json(maximum):
            raise ColumnarFormatError(f"column {name!r}: int64 stats must be int64 integers")
    elif col_type == "float64":
        if not _is_finite_json_float(minimum) or not _is_finite_json_float(maximum):
            raise ColumnarFormatError(f"column {name!r}: float64 stats must be finite numbers")
        minimum = float(minimum)
        maximum = float(maximum)
    elif col_type == "utf8":
        if not isinstance(minimum, str) or not isinstance(maximum, str):
            raise ColumnarFormatError(f"column {name!r}: utf8 stats must be strings")
    if minimum > maximum:
        raise ColumnarFormatError(f"column {name!r}: min exceeds max")


def _is_int64_json(value: Any) -> bool:
    return (
        isinstance(value, int)
        and not isinstance(value, bool)
        and -(2**63) <= value <= 2**63 - 1
    )


def _is_finite_json_float(value: Any) -> bool:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    value = float(value)
    return value == value and value not in (float("inf"), float("-inf"))


def _validate_header_v2(header: Any) -> dict:
    """Validate the JSON header of a row-group-partitioned (v2) file."""
    if not isinstance(header, dict):
        raise ColumnarFormatError("header must be a JSON object")
    unknown = set(header) - _V2_HEADER_KEYS
    if unknown:
        raise ColumnarFormatError(f"unknown header key(s): {sorted(unknown)!r}")
    compression = header.get("compression")
    if compression not in _COMPRESSION_NAMES:
        raise ColumnarFormatError(f"unknown compression in header: {compression!r}")
    row_count = header.get("row_count")
    if not _is_nonneg_int(row_count):
        raise ColumnarFormatError("header row_count must be a non-negative integer")
    row_group_size = header.get("row_group_size")
    if (
        not isinstance(row_group_size, int)
        or isinstance(row_group_size, bool)
        or row_group_size < 1
    ):
        raise ColumnarFormatError("header row_group_size must be a positive integer")
    data_length = header.get("data_length")
    if not _is_nonneg_int(data_length):
        raise ColumnarFormatError("header data_length must be a non-negative integer")
    entries = header.get("columns")
    if not isinstance(entries, list) or not entries:
        raise ColumnarFormatError("header must list at least one column")

    columns: list[dict] = []
    seen: set[str] = set()
    for pos, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise ColumnarFormatError(f"column header #{pos} must be an object")
        unknown_col = set(entry) - _V2_COLUMN_KEYS
        if unknown_col:
            raise ColumnarFormatError(
                f"column header #{pos}: unknown key(s) {sorted(unknown_col)!r}"
            )
        name = entry.get("name")
        if not isinstance(name, str) or not name:
            raise ColumnarFormatError(f"column header #{pos}: name must be a non-empty string")
        if name in seen:
            raise ColumnarFormatError(f"duplicate column in header: {name!r}")
        seen.add(name)
        col_type = entry.get("type")
        if col_type not in _TYPE_NAMES:
            raise ColumnarFormatError(f"column {name!r}: unknown type {col_type!r}")
        nullable = entry.get("nullable")
        if not isinstance(nullable, bool):
            raise ColumnarFormatError(f"column {name!r}: nullable must be true or false")
        encoding = entry.get("encoding")
        if encoding not in _ENCODING_NAMES:
            raise ColumnarFormatError(f"column {name!r}: unknown encoding {encoding!r}")
        if encoding == "dictionary" and col_type != "utf8":
            raise ColumnarFormatError(f"column {name!r}: dictionary encoding requires utf8")
        columns.append(entry)

    groups = header.get("row_groups")
    if not isinstance(groups, list):
        raise ColumnarFormatError("header row_groups must be a list")
    total_rows = 0
    next_offset = 0
    for pos, group in enumerate(groups):
        if not isinstance(group, dict):
            raise ColumnarFormatError(f"row group #{pos} must be an object")
        unknown_group = set(group) - _V2_GROUP_KEYS
        if unknown_group:
            raise ColumnarFormatError(
                f"row group #{pos}: unknown key(s) {sorted(unknown_group)!r}"
            )
        group_rows = group.get("row_count")
        if (
            not isinstance(group_rows, int)
            or isinstance(group_rows, bool)
            or group_rows < 1
        ):
            raise ColumnarFormatError(
                f"row group #{pos}: row_count must be a positive integer"
            )
        if pos < len(groups) - 1 and group_rows != row_group_size:
            raise ColumnarFormatError(
                f"row group #{pos}: row_count does not match row_group_size"
            )
        if group_rows > row_group_size:
            raise ColumnarFormatError(
                f"row group #{pos}: row_count exceeds row_group_size"
            )
        total_rows += group_rows
        blocks = group.get("columns")
        if not isinstance(blocks, list) or len(blocks) != len(columns):
            raise ColumnarFormatError(
                f"row group #{pos}: must carry one block per column"
            )
        for col, block in zip(columns, blocks):
            name = col["name"]
            if not isinstance(block, dict):
                raise ColumnarFormatError(
                    f"row group #{pos} column {name!r}: block must be an object"
                )
            unknown_block = set(block) - _V2_BLOCK_KEYS
            if unknown_block:
                raise ColumnarFormatError(
                    f"row group #{pos} column {name!r}: unknown key(s) "
                    f"{sorted(unknown_block)!r}"
                )
            for key in ("offset", "length", "uncompressed_length", "null_count"):
                if not _is_nonneg_int(block.get(key)):
                    raise ColumnarFormatError(
                        f"row group #{pos} column {name!r}: {key} must be a "
                        "non-negative integer"
                    )
            if not _is_uint32(block.get("crc32")):
                raise ColumnarFormatError(
                    f"row group #{pos} column {name!r}: crc32 must be a uint32"
                )
            if compression == "none" and block["length"] != block["uncompressed_length"]:
                raise ColumnarFormatError(
                    f"row group #{pos} column {name!r}: uncompressed block "
                    "length mismatch"
                )
            if block["offset"] != next_offset:
                raise ColumnarFormatError(
                    f"row group #{pos} column {name!r}: blocks are not contiguous"
                )
            next_offset += block["length"]
            null_count = block["null_count"]
            if null_count > group_rows:
                raise ColumnarFormatError(
                    f"row group #{pos} column {name!r}: null_count exceeds group row_count"
                )
            if not col["nullable"] and null_count:
                raise ColumnarFormatError(
                    f"row group #{pos} column {name!r}: NULL count set for "
                    "non-nullable column"
                )
            if "min" not in block or "max" not in block:
                raise ColumnarFormatError(
                    f"row group #{pos} column {name!r}: min and max keys are required"
                )
            _validate_stats(
                {"name": name, "min": block["min"], "max": block["max"]},
                col["type"],
                group_rows,
                null_count,
            )
    if total_rows != row_count:
        raise ColumnarFormatError("row group row counts do not add up to row_count")
    if next_offset != data_length:
        raise ColumnarFormatError("declared data length does not match column blocks")
    return header


# ---------------------------------------------------------------------------
# Writing
# ---------------------------------------------------------------------------


def _validate_write_options(
    table: Table, compression: Any, dictionary_encoding: Any
) -> frozenset:
    """Shared write-option validation; returns the dictionary column set.

    Everything is checked before any file is created, so invalid arguments
    never create or alter the destination.
    """
    if compression not in _COMPRESSION_NAMES:
        raise ValueError(f"unknown compression: {compression!r}")
    if isinstance(dictionary_encoding, str):
        raise ValueError("dictionary_encoding must be a sequence of column names")
    dict_names = tuple(dictionary_encoding)
    if len(set(dict_names)) != len(dict_names):
        raise ValueError("dictionary_encoding contains duplicate column names")
    unknown = [name for name in dict_names if name not in table.schema.names]
    if unknown:
        raise ValueError(f"dictionary_encoding references unknown column(s): {unknown!r}")
    for name in dict_names:
        col = table.schema.columns[table.schema.index(name)]
        if col.type != "utf8":
            raise ValueError(
                f"dictionary encoding is only valid for utf8 columns, not {col.name!r} ({col.type})"
            )
    return frozenset(dict_names)


def write_file(
    path: str | os.PathLike,
    table: Table,
    *,
    compression: str = "none",
    dictionary_encoding: Sequence[str] = (),
) -> None:
    """Write ``table`` to ``path`` deterministically and atomically.

    All validation happens before any file is created, so invalid arguments
    never create or alter the destination.
    """
    if not isinstance(table, Table):
        raise TypeError("table must be a Table instance")
    dict_set = _validate_write_options(table, compression, dictionary_encoding)

    raw_section = bytearray()
    chunk_info: list[dict] = []
    for i, col in enumerate(table.schema.columns):
        values = table._columns[i]
        payload, null_count, minimum, maximum = _encode_payload(
            col, values, use_dictionary=col.name in dict_set
        )
        chunk_info.append(
            {
                "name": col.name,
                "type": col.type,
                "nullable": col.nullable,
                "encoding": "dictionary" if col.name in dict_set else "plain",
                "offset": len(raw_section),
                "length": len(payload),
                "crc32": zlib.crc32(payload) & 0xFFFFFFFF,
                "null_count": null_count,
                "min": _stats_json(minimum),
                "max": _stats_json(maximum),
            }
        )
        raw_section.extend(payload)

    if compression == "zlib":
        data_section = zlib.compress(bytes(raw_section), level=6)
    else:
        data_section = bytes(raw_section)
    header = _build_header(table, compression, data_section, bytes(raw_section), chunk_info)
    header_bytes = _dump_json(header)
    if len(header_bytes) > _MAX_HEADER_BYTES:
        raise ValueError("serialized header exceeds the size limit")

    prefix = _MAGIC + bytes([FORMAT_VERSION]) + struct.pack("<I", len(header_bytes))
    body = prefix + header_bytes + data_section
    crc = zlib.crc32(body) & 0xFFFFFFFF
    blob = body + struct.pack("<I", crc) + _FOOTER_MARKER

    _atomic_write(path, blob)


def write_partitioned_file(
    path: str | os.PathLike,
    table: Table,
    row_group_size: int,
    *,
    compression: str = "none",
    dictionary_encoding: Sequence[str] = (),
) -> None:
    """Write ``table`` as a row-group-partitioned (v2) columnar file.

    Rows are split, in their original order, into consecutive groups of
    ``row_group_size`` rows (the last group holds the remainder; an empty
    table yields no groups).  Every group records its row count and, per
    column, ``null_count`` / ``min`` / ``max`` statistics; every
    (group, column) block is checksummed and -- with ``compression="zlib"``
    -- compressed independently, so readers can verify, decompress and
    decode exactly the blocks they need.

    The same inputs and options always produce identical bytes, and the
    destination is replaced atomically.  All validation happens before any
    file is created: a non-positive (or non-integer) ``row_group_size`` and
    invalid ``compression`` / ``dictionary_encoding`` arguments raise
    :class:`ValueError` without creating or altering the target.
    """
    if not isinstance(table, Table):
        raise TypeError("table must be a Table instance")
    if (
        not isinstance(row_group_size, int)
        or isinstance(row_group_size, bool)
        or row_group_size < 1
    ):
        raise ValueError("row_group_size must be a positive integer")
    dict_set = _validate_write_options(table, compression, dictionary_encoding)

    row_count = table.row_count
    group_bounds: list[tuple[int, int]] = []
    start = 0
    while start < row_count:
        end = min(start + row_group_size, row_count)
        group_bounds.append((start, end))
        start = end

    data_section = bytearray()
    group_headers: list[dict] = []
    for group_start, group_end in group_bounds:
        block_info: list[dict] = []
        for i, col in enumerate(table.schema.columns):
            values = table._columns[i][group_start:group_end]
            payload, null_count, minimum, maximum = _encode_payload(
                col, values, use_dictionary=col.name in dict_set
            )
            if compression == "zlib":
                stored = zlib.compress(payload, level=6)
            else:
                stored = payload
            block_info.append(
                {
                    "offset": len(data_section),
                    "length": len(stored),
                    "crc32": zlib.crc32(stored) & 0xFFFFFFFF,
                    "uncompressed_length": len(payload),
                    "null_count": null_count,
                    "min": _stats_json(minimum),
                    "max": _stats_json(maximum),
                }
            )
            data_section.extend(stored)
        group_headers.append(
            {"row_count": group_end - group_start, "columns": block_info}
        )

    header = {
        "compression": compression,
        "row_count": row_count,
        "row_group_size": row_group_size,
        "data_length": len(data_section),
        "columns": [
            {
                "name": col.name,
                "type": col.type,
                "nullable": col.nullable,
                "encoding": "dictionary" if col.name in dict_set else "plain",
            }
            for col in table.schema.columns
        ],
        "row_groups": group_headers,
    }
    header_bytes = _dump_json(header)
    if len(header_bytes) > _MAX_HEADER_BYTES:
        raise ValueError("serialized header exceeds the size limit")

    blob = (
        _MAGIC
        + bytes([FORMAT_VERSION_PARTITIONED])
        + struct.pack("<I", len(header_bytes))
        + header_bytes
        + bytes(data_section)
        + _FOOTER_MARKER
    )
    _atomic_write(path, blob)


def _atomic_write(path: str | os.PathLike, blob: bytes) -> None:
    path = os.fspath(path)
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_name = tempfile.mkstemp(prefix=".columnar-", suffix=".tmp", dir=directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(blob)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_name, path)
    except BaseException:
        try:
            os.unlink(tmp_name)
        except FileNotFoundError:
            pass
        raise


# ---------------------------------------------------------------------------
# Reading
# ---------------------------------------------------------------------------


def _read_exact(handle, size: int, what: str) -> bytes:
    data = handle.read(size)
    if len(data) != size:
        raise ColumnarFormatError(f"truncated file while reading {what}")
    return data


def _read_header(path: str | os.PathLike) -> tuple[bytes, bytes, dict, int, int]:
    """Read prefix + JSON header and fstat the declared total size.

    Metadata-only: no data bytes are touched. Returns the raw prefix, raw
    header bytes, the validated header dict, the on-disk file size and the
    format version.  Both v1 and v2 headers are accepted.
    """
    with open(path, "rb") as handle:
        prefix = handle.read(_PREFIX_LEN)
        if len(prefix) < _PREFIX_LEN:
            if not prefix:
                raise ColumnarFormatError("empty file")
            if len(prefix) >= 4 and prefix[:4] != _MAGIC:
                raise ColumnarFormatError("bad magic number")
            raise ColumnarFormatError("truncated file prefix")
        if prefix[:4] != _MAGIC:
            raise ColumnarFormatError("bad magic number")
        version = prefix[4]
        if version not in (FORMAT_VERSION, FORMAT_VERSION_PARTITIONED):
            raise ColumnarFormatError(f"unsupported format version: {version}")
        (header_length,) = struct.unpack("<I", prefix[5:9])
        if header_length == 0 or header_length > _MAX_HEADER_BYTES:
            raise ColumnarFormatError("header length out of bounds")
        header_bytes = _read_exact(handle, header_length, "header")
        actual_size = os.fstat(handle.fileno()).st_size

    try:
        header = json.loads(
            header_bytes.decode("utf-8"),
            object_pairs_hook=_reject_duplicate_keys,
            parse_constant=_reject_json_constant,
        )
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ColumnarFormatError(f"invalid header JSON: {exc}") from None
    if version == FORMAT_VERSION_PARTITIONED:
        header = _validate_header_v2(header)
        trailer_len = _V2_TRAILER_LEN
    else:
        header = _validate_header(header)
        trailer_len = _FOOTER_LEN

    expected_size = _PREFIX_LEN + header_length + header["data_length"] + trailer_len
    if actual_size != expected_size:
        raise ColumnarFormatError(
            f"file size {actual_size} does not match declared size {expected_size}"
        )
    return prefix, header_bytes, header, actual_size, version


def read_file(
    path: str | os.PathLike, *, columns: Sequence[str] | None = None
) -> Table:
    """Read a table, optionally projecting ``columns`` in the given order.

    Both format versions are accepted.  For v2 (row-group-partitioned)
    files only the blocks of the requested columns are decompressed and
    decoded; unreferenced column blocks are never touched beyond their
    declared sizes.
    """
    if columns is not None and not isinstance(columns, str):
        # Materialise once so one-shot iterables survive both the decode
        # set computation and the final projection.
        columns = tuple(columns)
    prefix, header_bytes, header, _, version = _read_header(path)
    if version == FORMAT_VERSION_PARTITIONED:
        table = _read_partitioned_table(
            path,
            columns=None if columns is None else set(columns),
            row_groups=None,
            _header=(header, _PREFIX_LEN + len(header_bytes)),
        )
    else:
        table = _read_v1(path, prefix, header_bytes, header)
    if columns is not None:
        table = table.project(columns)
    return table


def _read_v1(path: str | os.PathLike, prefix: bytes, header_bytes: bytes, header: dict) -> Table:
    with open(path, "rb") as handle:
        handle.seek(_PREFIX_LEN + len(header_bytes))
        data_section = _read_exact(handle, header["data_length"], "data section")
        footer = _read_exact(handle, _FOOTER_LEN, "footer")
        if handle.read(1):
            raise ColumnarFormatError("trailing bytes after footer")

    (footer_crc,) = struct.unpack("<I", footer[:4])
    if footer[4:] != _FOOTER_MARKER:
        raise ColumnarFormatError("bad end marker")
    covered = prefix + header_bytes + data_section
    if (zlib.crc32(covered) & 0xFFFFFFFF) != footer_crc:
        raise ColumnarFormatError("overall checksum mismatch")
    raw_section = _inflate(header, data_section)

    schema_cols = []
    decoded_columns = []
    for entry in header["columns"]:
        col = ColumnSchema(entry["name"], entry["type"], entry["nullable"])
        schema_cols.append(col)
        start = entry["offset"]
        end = start + entry["length"]
        if end > len(raw_section):
            raise ColumnarFormatError(f"column {col.name!r}: chunk outside data section")
        payload = raw_section[start:end]
        if (zlib.crc32(payload) & 0xFFFFFFFF) != entry["crc32"]:
            raise ColumnarFormatError(f"column {col.name!r}: checksum mismatch")
        values = _decode_column(col, entry["encoding"], header["row_count"], payload)
        _verify_stats(col, values, entry)
        decoded_columns.append(values)

    schema = Schema(schema_cols)
    return Table._from_storage(schema, decoded_columns)


class _UnreadColumn:
    """Placeholder for a v2 column whose blocks were not decoded.

    The query engine's bound plans only ever index referenced (decoded)
    columns, so placeholders are never actually read; any access yields
    ``None`` rather than failing loudly.
    """

    __slots__ = ("_length",)

    def __init__(self, length: int):
        self._length = length

    def __len__(self) -> int:
        return self._length

    def __getitem__(self, index):
        return None


def _schema_from_header_v2(header: dict) -> Schema:
    return Schema(
        [
            ColumnSchema(entry["name"], entry["type"], entry["nullable"])
            for entry in header["columns"]
        ]
    )


def _row_groups_from_header_v2(header: dict) -> list[dict]:
    """Per-group statistics of a validated v2 header, in file order."""
    names = [entry["name"] for entry in header["columns"]]
    return [
        {
            "row_count": group["row_count"],
            "columns": [
                {
                    "name": name,
                    "null_count": block["null_count"],
                    "min": block["min"],
                    "max": block["max"],
                }
                for name, block in zip(names, group["columns"])
            ],
        }
        for group in header["row_groups"]
    ]


def _read_partitioned_table(
    path: str | os.PathLike,
    columns: set[str] | None = None,
    row_groups: Sequence[int] | None = None,
    _header: tuple[dict, int] | None = None,
) -> Table:
    """Read selected columns and row groups of a v2 file.

    ``columns`` restricts which column blocks are decompressed and decoded
    (``None`` decodes all); ``row_groups`` restricts which groups contribute
    rows, in file order (``None`` takes every group).  The returned table
    carries the full schema; columns that were not decoded are inert
    placeholders.  Only the blocks actually read have their checksums,
    decompressed lengths and statistics verified.
    """
    if _header is None:
        _, header_bytes, header, _, version = _read_header(path)
        if version != FORMAT_VERSION_PARTITIONED:
            raise ColumnarFormatError("not a partitioned (v2) file")
        data_start = _PREFIX_LEN + len(header_bytes)
    else:
        header, data_start = _header
    schema = _schema_from_header_v2(header)
    names = schema.names
    if columns is None:
        decode_indices = set(range(len(names)))
    else:
        decode_indices = {i for i, name in enumerate(names) if name in columns}
    groups = header["row_groups"]
    group_indices = range(len(groups)) if row_groups is None else row_groups
    encodings = [entry["encoding"] for entry in header["columns"]]
    compression = header["compression"]

    decoded: dict[int, list] = {i: [] for i in decode_indices}
    total_rows = 0
    with open(path, "rb") as handle:
        handle.seek(-_V2_TRAILER_LEN, os.SEEK_END)
        if handle.read(_V2_TRAILER_LEN) != _FOOTER_MARKER:
            raise ColumnarFormatError("bad end marker")
        for group_index in group_indices:
            group = groups[group_index]
            group_rows = group["row_count"]
            total_rows += group_rows
            blocks = group["columns"]
            for i in decode_indices:
                block = blocks[i]
                handle.seek(data_start + block["offset"])
                stored = _read_exact(
                    handle, block["length"], f"block of column {names[i]!r}"
                )
                if (zlib.crc32(stored) & 0xFFFFFFFF) != block["crc32"]:
                    raise ColumnarFormatError(
                        f"column {names[i]!r}: block checksum mismatch"
                    )
                payload = _inflate_block(compression, stored, block)
                values = _decode_column(
                    schema.columns[i], encodings[i], group_rows, payload
                )
                _verify_stats(schema.columns[i], values, block)
                decoded[i].extend(values)

    out_columns: list = []
    for i in range(len(names)):
        if i in decode_indices:
            out_columns.append(tuple(decoded[i]))
        else:
            out_columns.append(_UnreadColumn(total_rows))
    table = Table.__new__(Table)
    table.schema = schema
    table._row_count = total_rows
    table._columns = tuple(out_columns)
    return table


def _inflate_block(compression: str, stored: bytes, block: dict) -> bytes:
    if compression == "zlib":
        try:
            payload = zlib.decompress(stored)
        except zlib.error as exc:
            raise ColumnarFormatError(f"cannot decompress column block: {exc}") from None
    else:
        payload = stored
    if len(payload) != block["uncompressed_length"]:
        raise ColumnarFormatError("uncompressed block length mismatch")
    return payload


def _inflate(header: dict, data_section: bytes) -> bytes:
    if (zlib.crc32(data_section) & 0xFFFFFFFF) != header["data_crc32"]:
        raise ColumnarFormatError("data section checksum mismatch")
    if header["compression"] == "zlib":
        try:
            raw_section = zlib.decompress(data_section)
        except zlib.error as exc:
            raise ColumnarFormatError(f"cannot decompress data section: {exc}") from None
    else:
        raw_section = data_section
    if len(raw_section) != header["uncompressed_length"]:
        raise ColumnarFormatError("uncompressed data length mismatch")
    return raw_section


def _verify_stats(col: ColumnSchema, values: Sequence, entry: dict) -> None:
    null_count = sum(1 for value in values if value is None)
    if null_count != entry["null_count"]:
        raise ColumnarFormatError(f"column {col.name!r}: null_count mismatch")
    present = [value for value in values if value is not None]
    if not present:
        if entry["min"] is not None or entry["max"] is not None:
            raise ColumnarFormatError(f"column {col.name!r}: stats mismatch")
        return
    minimum = min(present)
    maximum = max(present)
    meta_min = entry["min"]
    meta_max = entry["max"]
    if col.type == "float64":
        meta_min = float(meta_min)
        meta_max = float(meta_max)
    if minimum != meta_min or maximum != meta_max:
        raise ColumnarFormatError(f"column {col.name!r}: min/max mismatch")


def inspect_file(path: str | os.PathLike) -> dict:
    """Read only the file metadata; no data bytes are read, decompressed or decoded.

    Returns a dict with fixed key order: ``format_version``, ``row_count``,
    ``columns``; columns stay in schema order, each with keys ``name``,
    ``type``, ``nullable``, ``row_count``, ``null_count``, ``min``, ``max``.
    For v2 (row-group-partitioned) files the column statistics are the
    aggregates of the per-group statistics.
    """
    _, _, header, _, version = _read_header(path)
    if version == FORMAT_VERSION_PARTITIONED:
        groups = _row_groups_from_header_v2(header)
        columns = []
        for i, entry in enumerate(header["columns"]):
            null_count = sum(group["columns"][i]["null_count"] for group in groups)
            present_min = [
                group["columns"][i]["min"]
                for group in groups
                if group["columns"][i]["min"] is not None
            ]
            present_max = [
                group["columns"][i]["max"]
                for group in groups
                if group["columns"][i]["max"] is not None
            ]
            columns.append(
                {
                    "name": entry["name"],
                    "type": entry["type"],
                    "nullable": entry["nullable"],
                    "row_count": header["row_count"],
                    "null_count": null_count,
                    "min": min(present_min) if present_min else None,
                    "max": max(present_max) if present_max else None,
                }
            )
        return {
            "format_version": FORMAT_VERSION_PARTITIONED,
            "row_count": header["row_count"],
            "columns": columns,
        }
    return {
        "format_version": FORMAT_VERSION,
        "row_count": header["row_count"],
        "columns": [
            {
                "name": entry["name"],
                "type": entry["type"],
                "nullable": entry["nullable"],
                "row_count": header["row_count"],
                "null_count": entry["null_count"],
                "min": entry["min"],
                "max": entry["max"],
            }
            for entry in header["columns"]
        ],
    }


def inspect_row_groups(path: str | os.PathLike) -> list[dict]:
    """Read only the file metadata and return per-row-group statistics.

    For a v2 (row-group-partitioned) file the result lists one entry per
    row group, in file order; each entry carries the group's ``row_count``
    and its per-column statistics (``name``, ``null_count``, ``min``,
    ``max``) in schema order.  A v1 file has no row groups and yields an
    empty list.  No data bytes are read, decompressed or decoded.
    """
    _, _, header, _, version = _read_header(path)
    if version != FORMAT_VERSION_PARTITIONED:
        return []
    return _row_groups_from_header_v2(header)

"""Binding: resolve a parsed statement against one schema.

The binder consumes the parsed :class:`~columnar_analytics.parser._Select`
tree and a :class:`~columnar_analytics.format.Schema` (single-file,
combined join or metadata-derived -- all the same kind) and produces the
bound plan dict: validated projection items, the bound WHERE / HAVING
expression IR, ORDER BY keys and the aggregate registry.  It performs no
file access of its own, so a statement can be bound against metadata alone
(the explain path) or against a fully read table (the execution path) with
identical results and identical
:class:`~columnar_analytics.errors.QueryValidationError` behaviour.
"""

from __future__ import annotations

from dataclasses import dataclass

from .errors import QuerySyntaxError, QueryValidationError
from .expr import (
    _Aggregate,
    _Case,
    _Column,
    _Cmp,
    _Expr,
    _In,
    _IsNull,
    _Literal,
    _Logic,
    _Not,
    _bind_expr,
    _check_comparison_types,
    _check_in_types,
    _require_boolean,
)
from .format import ColumnSchema, Schema
from .parser import _RefItem, _Select


# ---------------------------------------------------------------------------
# Binding: schema resolution, projection checks and type compatibility
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class _BoundItem:
    """A validated projection element."""

    kind: str  # "column" | "agg" | "expr"
    output_name: str
    # kind == "column":
    col_index: int = -1
    # kind == "agg":
    func: str = ""
    arg_index: int = -1  # -1 means COUNT(*)
    arg_type: str = ""
    distinct: bool = False  # argument values are deduplicated per group
    # kind == "expr":
    expr: tuple | None = None  # bound scalar expression
    out_type: str = ""
    nullable: bool = True


def _bind_select(select: _Select, schema: Schema, expected_table="input") -> dict:
    if expected_table is not None:
        table_matches = (
            select.table == expected_table
            if select.table_quoted
            else select.table.lower() == expected_table.lower()
        )
        if not table_matches:
            raise QueryValidationError(
                f"unknown table {select.table!r}; only {expected_table!r} is supported"
            )

    where = _bind_expr(select.where, schema) if select.where is not None else None
    if where is not None and where.type != "bool":
        raise QueryValidationError(
            f"WHERE clause must be boolean, got {where.type}"
        )

    if select.distinct and select.is_aggregate_query:
        raise QueryValidationError(
            "DISTINCT is not allowed with GROUP BY, HAVING or aggregate projections"
        )

    if not select.is_aggregate_query:
        return _bind_plain(select, schema, where)
    return _bind_aggregate(select, schema, where)


def _bind_plain(select: _Select, schema: Schema, where) -> dict:
    # Non-aggregate path: '*' or a comma-separated list of plain columns and
    # computed scalar expressions (each named with AS).
    bound_items: list[_BoundItem] = []
    if select.star:
        for i, col in enumerate(schema.columns):
            bound_items.append(
                _BoundItem(
                    "column",
                    output_name=col.name,
                    col_index=i,
                    out_type=col.type,
                    nullable=col.nullable,
                )
            )
    else:
        output_seen: set[str] = set()
        for item in select.items:
            if item.kind == "star":
                # A star mixed into a plain projection remains grammatical.
                raise QuerySyntaxError("'*' cannot be mixed with other projection items")
            if item.kind == "column":
                name = item.name
                if name in output_seen:
                    raise QueryValidationError(
                        f"duplicate column in projection: {name!r}"
                    )
                try:
                    col_index = schema.index(name)
                except KeyError:
                    raise QueryValidationError(f"unknown column: {name!r}") from None
                col = schema.columns[col_index]
                output_seen.add(col.name)
                bound_items.append(
                    _BoundItem(
                        "column",
                        output_name=col.name,
                        col_index=col_index,
                        out_type=col.type,
                        nullable=col.nullable,
                    )
                )
            else:  # "expr"
                expr = _bind_expr(item.expr, schema)
                out_type = expr.type
                # Arithmetic scalar expressions stay numeric-only; a CASE
                # expression may additionally yield bool or utf8 results
                # (its own WHEN/ELSE type consistency is checked at binding).
                if isinstance(expr, _Case):
                    allowed_types = ("int64", "float64", "bool", "utf8")
                else:
                    allowed_types = ("int64", "float64")
                if out_type not in allowed_types:
                    raise QueryValidationError(
                        f"SELECT expression must be numeric, got {out_type}"
                    )
                alias = item.name
                if alias in output_seen:
                    raise QueryValidationError(f"duplicate result column: {alias!r}")
                output_seen.add(alias)
                bound_items.append(
                    _BoundItem(
                        "expr",
                        output_name=alias,
                        expr=expr,
                        out_type=out_type,
                        nullable=expr.nullable,
                    )
                )
    aliases = {
        item.output_name: item.expr for item in bound_items if item.kind == "expr"
    }
    projected = {item.output_name: i for i, item in enumerate(bound_items)}
    order_by = _bind_plain_order_by(
        select.order_by, schema, aliases, select.distinct, projected
    )
    return {
        "mode": "plain",
        "items": tuple(bound_items),
        "aggregates": (),
        "where": where,
        "having": None,
        "order_by": order_by,
        "distinct": select.distinct,
    }


def _bind_plain_order_by(
    select_order_by, schema: Schema, aliases: dict, distinct: bool, projected: dict
):
    if select_order_by is None:
        return None
    bound: list[tuple] = []
    order_seen: set[str] = set()
    for item in select_order_by:
        if item.kind == "agg":
            raise QueryValidationError(
                f"aggregate {item.func}({_arg_label(item)}) may appear in ORDER BY "
                "only as part of an aggregate query"
            )
        name = item.name
        if name in order_seen:
            raise QueryValidationError(
                f"duplicate column in ORDER BY: {name!r}"
            )
        order_seen.add(name)
        nulls_first = item.nulls_first if item.nulls_first is not None else False
        if distinct:
            # A DISTINCT query sorts its deduplicated result rows, so every
            # ORDER BY name must be one of the projected outputs (a bare
            # projected column or an explicit AS alias).
            if name not in projected:
                try:
                    schema.index(name)
                except KeyError:
                    raise QueryValidationError(
                        f"unknown ORDER BY column: {name!r}"
                    ) from None
                raise QueryValidationError(
                    f"ORDER BY column {name!r} is not part of the SELECT DISTINCT results"
                )
            bound.append(("out", projected[name], item.descending, nulls_first))
            continue
        # A SELECT alias shadows an input column of the same name.
        if name in aliases:
            bound.append(("expr", aliases[name], item.descending, nulls_first))
            continue
        try:
            col_index = schema.index(name)
        except KeyError:
            raise QueryValidationError(
                f"unknown ORDER BY column: {name!r}"
            ) from None
        bound.append(("col", col_index, item.descending, nulls_first))
    return tuple(bound)


def _bind_aggregate(select: _Select, schema: Schema, where) -> dict:
    if select.star:
        raise QueryValidationError("'*' cannot be combined with aggregates or GROUP BY")

    if (
        select.having is not None
        and select.group_by is None
        and not select.has_aggregate
        and not _having_tree_has_aggregate(select.having)
    ):
        # HAVING filters formed groups; without aggregation or GROUP BY the
        # statement stays a non-aggregate query and HAVING has no meaning.
        raise QueryValidationError(
            "HAVING is only valid with GROUP BY or an aggregate"
        )

    # Resolve GROUP BY columns first: order matters for the grouping key, and
    # duplicates / unknown columns are rejected here.  Entries are
    # (table, table_quoted, name) triples; names reaching the binder are
    # already canonical (single-file queries never carry a qualifier).
    group_indices: list[int] = []
    group_seen: set[str] = set()
    for _table, _table_quoted, name in select.group_by or ():
        if name in group_seen:
            raise QueryValidationError(f"duplicate column in GROUP BY: {name!r}")
        group_seen.add(name)
        try:
            group_indices.append(schema.index(name))
        except KeyError:
            raise QueryValidationError(f"unknown GROUP BY column: {name!r}") from None
    group_index_set = set(group_indices)

    # One registry of distinct aggregates shared by SELECT, HAVING and ORDER
    # BY, keyed by (function, argument index, DISTINCT flag) and kept in
    # first-reference order.  HAVING-only aggregates are computed but never
    # projected.
    agg_registry: dict[tuple, int] = {}
    agg_order: list[_BoundItem] = []

    def require_aggregate(func: str, arg_name: str, distinct: bool = False) -> int:
        arg_index, arg_col, label, out_type, nullable = _resolve_agg_call(
            func, arg_name, schema, distinct
        )
        key = (func, arg_index, distinct)
        slot = agg_registry.get(key)
        if slot is None:
            slot = len(agg_order)
            agg_registry[key] = slot
            agg_order.append(
                _BoundItem(
                    "agg",
                    output_name=label,
                    func=func,
                    arg_index=arg_index,
                    arg_type=arg_col.type if arg_col is not None else "",
                    distinct=distinct,
                    out_type=out_type,
                    nullable=nullable,
                )
            )
        return slot

    # Resolve the projection.  Plain columns must be grouped; output names
    # (group column names and canonical "FUNC(arg)" labels) must be unique.
    bound_items: list[_BoundItem] = []
    output_seen: set[str] = set()
    has_plain = False
    for item in select.items:
        if item.kind == "star":
            raise QueryValidationError(
                "'*' cannot be combined with aggregates or GROUP BY"
            )
        if item.kind == "expr":
            raise QueryValidationError(
                "scalar expressions are not supported in aggregate queries"
            )
        if item.kind == "column":
            has_plain = True
            name = item.name
            try:
                col_index = schema.index(name)
            except KeyError:
                raise QueryValidationError(f"unknown column: {name!r}") from None
            if col_index not in group_index_set:
                raise QueryValidationError(
                    f"column {name!r} must appear in GROUP BY or be wrapped in an aggregate"
                )
            label = name
            if label in output_seen:
                raise QueryValidationError(f"duplicate result column: {name!r}")
            output_seen.add(label)
            col = schema.columns[col_index]
            bound_items.append(
                _BoundItem(
                    "column",
                    output_name=label,
                    col_index=col_index,
                    out_type=col.type,
                    nullable=col.nullable,
                )
            )
        else:
            slot = require_aggregate(item.func, item.arg, item.distinct)
            agg_item = agg_order[slot]
            if agg_item.output_name in output_seen:
                raise QueryValidationError(
                    f"duplicate result column: {agg_item.output_name!r}"
                )
            output_seen.add(agg_item.output_name)
            bound_items.append(agg_item)

    if select.group_by is None and has_plain:
        # No grouping: every projected column must be an aggregate.
        raise QueryValidationError(
            "without GROUP BY, the projection may contain aggregates only"
        )

    # HAVING filters the formed groups; it may reuse projected aggregates and
    # may introduce further aggregates that never reach the projection.
    having = None
    if select.having is not None:
        having = _bind_having(
            select.having, schema, group_index_set, agg_order, require_aggregate
        )
        _require_boolean(having, "HAVING clause")

    order_by = _bind_aggregate_order_by(
        select.order_by, bound_items, schema
    )
    return {
        "mode": "aggregate",
        "group_indices": tuple(group_indices),
        "items": tuple(bound_items),
        "aggregates": tuple(agg_order),
        "where": where,
        "having": having,
        "order_by": order_by,
        "distinct": False,
    }


def _having_tree_has_aggregate(node: tuple) -> bool:
    """Whether a parsed (unbound) HAVING tree names at least one aggregate."""
    tag = node[0]
    if tag == "hagg":
        return True
    if tag in ("literal", "column"):
        return False
    if tag in ("not", "isnull"):
        return _having_tree_has_aggregate(node[1])
    if tag == "cmp":
        return _having_tree_has_aggregate(node[2]) or _having_tree_has_aggregate(
            node[3]
        )
    if tag == "in":
        # Options are parser-restricted to constants; only the operand can
        # name an aggregate.
        return _having_tree_has_aggregate(node[1])
    return _having_tree_has_aggregate(node[1]) or _having_tree_has_aggregate(node[2])


def _bind_having(
    node: tuple,
    schema: Schema,
    group_index_set: set[int],
    agg_order: list[_BoundItem],
    require_aggregate,
) -> _Expr:
    tag = node[0]
    if tag == "literal":
        return _Literal(node[1], node[2])
    if tag == "column":
        name = node[1]
        try:
            col_index = schema.index(name)
        except KeyError:
            raise QueryValidationError(f"unknown column: {name!r}") from None
        if col_index not in group_index_set:
            raise QueryValidationError(
                f"HAVING column {name!r} must appear in GROUP BY or be wrapped in an aggregate"
            )
        col = schema.columns[col_index]
        return _Column(name, col_index, col.type, col.nullable)
    if tag == "hagg":
        slot = require_aggregate(node[1], node[2], node[5])
        agg_item = agg_order[slot]
        arg_name = (
            None
            if agg_item.arg_index < 0
            else schema.columns[agg_item.arg_index].name
        )
        return _Aggregate(
            agg_item.func,
            slot,
            arg_name,
            agg_item.distinct,
            agg_item.out_type,
            agg_item.nullable,
        )
    if tag == "not":
        operand = _bind_having(
            node[1], schema, group_index_set, agg_order, require_aggregate
        )
        _require_boolean(operand, "NOT")
        return _Not(operand)
    if tag in ("and", "or"):
        left = _bind_having(
            node[1], schema, group_index_set, agg_order, require_aggregate
        )
        right = _bind_having(
            node[2], schema, group_index_set, agg_order, require_aggregate
        )
        _require_boolean(left, tag.upper())
        _require_boolean(right, tag.upper())
        return _Logic(tag, left, right)
    if tag == "isnull":
        operand = _bind_having(
            node[1], schema, group_index_set, agg_order, require_aggregate
        )
        if not operand.is_having_leaf:
            raise QuerySyntaxError(
                "IS NULL operand must be a group column, an aggregate or a literal"
            )
        return _IsNull(operand, node[2])
    if tag == "cmp":
        op = node[1]
        left = _bind_having(
            node[2], schema, group_index_set, agg_order, require_aggregate
        )
        right = _bind_having(
            node[3], schema, group_index_set, agg_order, require_aggregate
        )
        if not (left.is_having_leaf and right.is_having_leaf):
            raise QuerySyntaxError(
                "comparison operands must be group columns, aggregates or literals"
            )
        _check_comparison_types(op, left, right)
        return _Cmp(op, left, right)
    if tag == "in":
        operand = _bind_having(
            node[1], schema, group_index_set, agg_order, require_aggregate
        )
        if not operand.is_having_leaf:
            raise QuerySyntaxError(
                "IN operand must be a group column, an aggregate or a literal"
            )
        options = tuple(
            _bind_having(
                option, schema, group_index_set, agg_order, require_aggregate
            )
            for option in node[3]
        )
        _check_in_types(operand, options)
        return _In(operand, options, node[2])
    raise QuerySyntaxError(f"unsupported expression: {tag}")  # pragma: no cover - defensive


def _agg_result_type(func: str, arg_col: ColumnSchema | None) -> tuple[str, bool]:
    """Static (type, nullable) of an aggregate call; rejects illegal args."""
    if func == "COUNT":
        return "int64", False
    if func == "SUM":
        if arg_col.type not in ("int64", "float64"):
            raise QueryValidationError(
                f"SUM requires an int64 or float64 argument, got {arg_col.type}"
            )
        return arg_col.type, True
    if func == "AVG":
        if arg_col.type not in ("int64", "float64"):
            raise QueryValidationError(
                f"AVG requires an int64 or float64 argument, got {arg_col.type}"
            )
        return "float64", True
    # MIN / MAX accept all four existing types.
    return arg_col.type, True


def _resolve_agg_call(
    func: str, arg_name: str, schema: Schema, distinct: bool = False
) -> tuple[int, ColumnSchema | None, str, str, bool]:
    """Resolve one aggregate call to (arg_index, arg_col|None, label, type, nullable)."""
    if arg_name == "":
        if func != "COUNT":
            raise QuerySyntaxError(f"{func} does not accept '*'")
        out_type, nullable = _agg_result_type("COUNT", None)
        return -1, None, "COUNT(*)", out_type, nullable
    try:
        arg_index = schema.index(arg_name)
    except KeyError:
        raise QueryValidationError(f"unknown column: {arg_name!r}") from None
    arg_col = schema.columns[arg_index]
    out_type, nullable = _agg_result_type(func, arg_col)
    # The result label uses the column name as spelled in the schema.
    if distinct:
        return (
            arg_index,
            arg_col,
            f"{func}(DISTINCT {arg_col.name})",
            out_type,
            nullable,
        )
    return arg_index, arg_col, f"{func}({arg_col.name})", out_type, nullable


def _arg_label(item: _RefItem) -> str:
    return "*" if item.arg == "" else item.arg


def _bind_aggregate_order_by(
    select_order_by,
    bound_items: list[_BoundItem],
    schema: Schema,
):
    if select_order_by is None:
        return None

    # Map every SELECT result to its output position.  ORDER BY in an
    # aggregate query may only name those selected results.
    selected: dict[tuple, int] = {}
    for i, bound in enumerate(bound_items):
        if bound.kind == "column":
            selected[("column", schema.columns[bound.col_index].name)] = i
        else:
            arg_key = "*" if bound.arg_index == -1 else schema.columns[bound.arg_index].name
            selected[("agg", f"{bound.func}|{arg_key}|{bound.distinct}")] = i

    bound_order: list[tuple[int, bool, bool]] = []
    order_seen: set[str] = set()
    for item in select_order_by:
        if item.kind == "column":
            key = ("column", item.name)
            label = item.name
            if key not in selected:
                # Keep the same "unknown column" wording for names the schema
                # does not know at all; anything else is an unselected result.
                try:
                    schema.index(item.name)
                except KeyError:
                    raise QueryValidationError(
                        f"unknown ORDER BY column: {item.name!r}"
                    ) from None
                raise QueryValidationError(
                    f"ORDER BY column {item.name!r} is not part of the selected results"
                )
        else:
            if item.arg == "":
                arg_key = "*"
                label = "COUNT(*)"
            else:
                try:
                    real_name = schema.columns[schema.index(item.arg)].name
                except KeyError:
                    raise QueryValidationError(
                        f"unknown ORDER BY column: {item.arg!r}"
                    ) from None
                arg_key = real_name
                if item.distinct:
                    label = f"{item.func}(DISTINCT {real_name})"
                else:
                    label = f"{item.func}({real_name})"
            key = ("agg", f"{item.func}|{arg_key}|{item.distinct}")
            if key not in selected:
                raise QueryValidationError(
                    f"ORDER BY aggregate {label} is not part of the selected results"
                )
        if label in order_seen:
            raise QueryValidationError(f"duplicate column in ORDER BY: {label!r}")
        order_seen.add(label)
        nulls_first = item.nulls_first if item.nulls_first is not None else False
        bound_order.append((selected[key], item.descending, nulls_first))
    return tuple(bound_order)
def _collect_expr_columns(node: _Expr, indices: set) -> None:
    """Add every source-column index referenced by one bound expression.

    One traversal for WHERE, SELECT expressions, ORDER BY aliases and the
    HAVING tree: the node hierarchy itself owns the walk.  HAVING
    aggregate leaves reference no source column here -- their arguments
    are scanned separately through the aggregate registry.
    """
    indices.update(node.columns())


def _collect_required_indices(bound: Mapping) -> set:
    """Combined-schema column indices referenced anywhere in the query."""
    indices: set = set(bound.get("group_indices", ()))
    if bound["where"] is not None:
        _collect_expr_columns(bound["where"], indices)
    for item in bound["items"]:
        if item.kind == "column":
            indices.add(item.col_index)
        elif item.kind == "agg":
            if item.arg_index >= 0:
                indices.add(item.arg_index)
        else:  # "expr"
            _collect_expr_columns(item.expr, indices)
    # Aggregates introduced only by HAVING still have to be scanned.
    for item in bound.get("aggregates", ()):
        if item.arg_index >= 0:
            indices.add(item.arg_index)
    if bound.get("having") is not None:
        _collect_expr_columns(bound["having"], indices)
    for entry in bound["order_by"] or ():
        if entry[0] == "col":
            indices.add(entry[1])
        elif entry[0] == "expr":
            _collect_expr_columns(entry[1], indices)
        # Aggregate ORDER BY entries index a selected output column, which
        # is already covered by the projection scan above.
    return indices

"""Command line entry point for columnar-analytics-engine."""

from __future__ import annotations

import argparse
import json
import sys

from . import __version__
from .export import export_query_file, export_query_files
from .format import ColumnarFormatError, inspect_file
from .query import (
    QuerySyntaxError,
    QueryValidationError,
    explain_file,
    explain_files,
    query_file,
    query_files,
)

_QUERY_ERRORS = (QuerySyntaxError, QueryValidationError, ColumnarFormatError)


def _write_json(payload) -> int:
    out = sys.stdout
    try:
        out.reconfigure(encoding="utf-8")
    except (AttributeError, ValueError):
        pass
    json.dump(payload, out, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
    out.write("\n")
    return 0


def _print_query_result(table) -> int:
    payload = {
        "columns": [
            {"name": col.name, "type": col.type, "nullable": col.nullable}
            for col in table.schema.columns
        ],
        "rows": [
            [table._columns[c][r] for c in range(len(table.schema.columns))]
            for r in range(table.row_count)
        ],
    }
    return _write_json(payload)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="columnar-analytics-engine", description="Columnar analytics engine with a SQL subset and vectorised execution")
    sub = parser.add_subparsers(dest="command")
    sub.add_parser("version", help="print the current version")
    inspect_parser = sub.add_parser("inspect", help="inspect a columnar file and print its metadata as JSON")
    inspect_parser.add_argument("path", help="path to the columnar file")
    query_parser = sub.add_parser("query", help="query a columnar file with SQL and print JSON")
    query_parser.add_argument("path", help="path to the columnar file")
    query_parser.add_argument("sql", help="SELECT statement to run against the file")
    query_files_parser = sub.add_parser("query-files", help="query mapped columnar files with a deterministic join chain and print JSON")
    query_files_parser.add_argument("sources", help="JSON object mapping table names to columnar file paths")
    query_files_parser.add_argument("sql", help="SELECT statement to run against the mapped tables")
    query_files_parser.add_argument(
        "--join-strategy",
        dest="join_strategy",
        default=None,
        help="join algorithm for a JOIN statement: hash or sort_merge (default: engine-chosen)",
    )
    explain_parser = sub.add_parser("explain", help="explain a SQL statement against a columnar file and print the plan JSON")
    explain_parser.add_argument("path", help="path to the columnar file")
    explain_parser.add_argument("sql", help="SELECT statement to plan against the file")
    explain_files_parser = sub.add_parser("explain-files", help="explain a SQL statement against mapped tables and print the plan JSON")
    explain_files_parser.add_argument("sources", help="JSON object mapping table names to columnar file paths")
    explain_files_parser.add_argument("sql", help="SELECT statement to plan against the mapped tables")
    explain_files_parser.add_argument(
        "--join-strategy",
        dest="join_strategy",
        default=None,
        help="join strategy recorded on the Join operator: hash (HASH) or sort_merge (SORT_MERGE)",
    )
    export_parser = sub.add_parser("export", help="query a columnar file with SQL and export the result as CSV or JSONL")
    export_parser.add_argument("path", help="path to the columnar file")
    export_parser.add_argument("sql", help="SELECT statement to run against the file")
    export_parser.add_argument("destination", help="path of the file to write")
    export_parser.add_argument("--format", default="csv", help="export format: csv (default) or jsonl")
    export_files_parser = sub.add_parser("export-files", help="query mapped tables with a join chain and export the result as CSV or JSONL")
    export_files_parser.add_argument("sources", help="JSON object mapping table names to columnar file paths")
    export_files_parser.add_argument("sql", help="SELECT statement to run against the mapped tables")
    export_files_parser.add_argument("destination", help="path of the file to write")
    export_files_parser.add_argument("--format", default="csv", help="export format: csv (default) or jsonl")
    export_files_parser.add_argument(
        "--join-strategy",
        dest="join_strategy",
        default=None,
        help="join algorithm for a JOIN statement: hash or sort_merge (default: engine-chosen)",
    )
    args = parser.parse_args(argv)

    if args.command == "version":
        print(__version__)
        return 0

    if args.command == "inspect":
        try:
            metadata = inspect_file(args.path)
        except ColumnarFormatError as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            return 1
        out = sys.stdout
        try:
            out.reconfigure(encoding="utf-8")
        except (AttributeError, ValueError):
            pass
        json.dump(metadata, out, ensure_ascii=False, separators=(",", ":"))
        out.write("\n")
        return 0

    if args.command == "query":
        try:
            table = query_file(args.path, args.sql)
        except _QUERY_ERRORS as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            return 1
        return _print_query_result(table)

    if args.command == "query-files":
        try:
            sources = json.loads(args.sources)
        except json.JSONDecodeError as exc:
            print(f"invalid sources JSON: {exc}", file=sys.stderr)
            return 2
        try:
            table = query_files(sources, args.sql, args.join_strategy)
        except _QUERY_ERRORS as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except ValueError as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            return 1
        return _print_query_result(table)

    if args.command == "explain":
        try:
            plan = explain_file(args.path, args.sql)
        except _QUERY_ERRORS as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            return 1
        return _write_json(plan)

    if args.command == "explain-files":
        try:
            sources = json.loads(args.sources)
        except json.JSONDecodeError as exc:
            print(f"invalid sources JSON: {exc}", file=sys.stderr)
            return 2
        try:
            plan = explain_files(sources, args.sql, args.join_strategy)
        except _QUERY_ERRORS as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except ValueError as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            return 1
        return _write_json(plan)

    if args.command == "export":
        try:
            export_query_file(args.path, args.sql, args.destination, args.format)
        except _QUERY_ERRORS as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except ValueError as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            return 1
        return 0

    if args.command == "export-files":
        try:
            sources = json.loads(args.sources)
        except json.JSONDecodeError as exc:
            print(f"invalid sources JSON: {exc}", file=sys.stderr)
            return 2
        try:
            export_query_files(sources, args.sql, args.destination, args.format, args.join_strategy)
        except _QUERY_ERRORS as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except ValueError as exc:
            print(str(exc), file=sys.stderr)
            return 2
        except OSError as exc:
            print(str(exc), file=sys.stderr)
            return 1
        return 0

    parser.print_help()
    return 0


if __name__ == "__main__":
    sys.exit(main())

